-- تصحيحات تدقيق جدول consultant_scenarios (الجولة الكاملة)
-- ===========================================================================
-- المصدر: تدقيق شامل للصفوف 111 مقابل النصوص الأولية للقانون التركي
-- والمصادر الرسمية (gov.tr)، ثم تفنيد عدائي لكل ملاحظة. لا يدخل هذا الملف
-- إلا ما ثبت عند المدقّق وصمد عند مفنِّد مستقل واحد على الأقل، وكل نصّ بديل
-- إمّا نصّ المدقّق المؤكَّد أو النصّ الأدقّ الذي فرضه المفنِّد.
-- steps و docs من نوع jsonb. شغّله في Supabase → SQL Editor.

UPDATE consultant_scenarios SET
    cost = 'فك الحجز لا يكلف رسوماً إضافية، لكن الدين الأصلي + فوائد التأخير يجب تسويته. أتعاب المحامي محكومة بتعرفة الحد الأدنى لأتعاب المحاماة الصادرة في الجريدة الرسمية، ولا يجوز الاتفاق على أقل منها. لعام 2026: 9,000 ليرة كحد أدنى لمتابعة تنفيذ في دائرة التنفيذ، و18,000 ليرة لدعوى بجلسة أمام محكمة التنفيذ. وإذا كان النزاع على مبلغ مالي تُحتسب الأتعاب نسبياً (16% عن أول 600,000 ليرة) وقد تتجاوز هذه المبالغ بكثير.',
    legal = 'القانون لا يحمي نسبة ثابتة من الحد الأدنى للأجور. المادة 83 من قانون التنفيذ والإفلاس (İcra ve İflas Kanunu) تنص على أن الرواتب والأجور تُحجز بعد خصم المبلغ الذي يقدّره مأمور التنفيذ لمعيشتك ومعيشة أسرتك، على ألّا يقلّ المبلغ المحجوز عن رُبع الراتب. أي أن أقصى ما يمكن حمايته هو ثلاثة أرباع راتبك أنت — والتقدير بيد مأمور التنفيذ — وليس نسبة من الحد الأدنى للأجور. (الحد الأدنى للأجور في تركيا لعام 2026: 33,030 ليرة إجمالي و28,075.50 ليرة صافي شهرياً (وزارة العمل والضمان الاجتماعي، سارٍ من 1/1/2026).). قانون İcra ve İflas (التنفيذ والإفلاس) المادة 83.',
    steps = '["اتصل بالبنك فوراً لمعرفة سبب التجميد (İcra haciz / MASAK bloke / Mahkeme kararı).", "إذا كان بسبب İcra (دين): راجع دائرة التنفيذ (İcra Müdürlüğü) لمعرفة تفاصيل الدين. يمكنك الدفع أو التفاوض على تقسيط.", "إذا كان بسبب MASAK: ستحتاج تقديم مستندات تثبت مشروعية مصدر الأموال (كشوف رواتب، عقود، فواتير).", "إذا كان بأمر قضائي: تحتاج محامياً لمتابعة القضية والطعن في القرار.", "لفك الحجز الجزئي: يمكنك تحرير مبالغ ضمن الحد المُعفى (لفك الحجز الجزئي: الرواتب تُحجز بعد خصم ما يقدّره مأمور التنفيذ لمعيشتك ومعيشة أسرتك، على ألّا يقلّ المحجوز عن رُبع الراتب (المادة 83 من قانون التنفيذ والإفلاس). أما رواتب التقاعد ومخصصات ومنافع مؤسسة الضمان الاجتماعي SGK فهي غير قابلة للحجز نهائياً بموجب المادة 93 من القانون 5510، إلا لدين نفقة أو دين للمؤسسة نفسها، ويجب على مأمور التنفيذ رفض طلب حجزها ما لم توقّع أنت موافقة — فلا توقّع أي موافقة (muvafakat) على حجز معاشك.).", "بعد التسوية، اطلب من الجهة المعنية إرسال \"فك الحجز\" (Haciz fekki) للبنك."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'bank-block';

UPDATE consultant_scenarios SET
    description = 'القيادة برخصة أجنبية في تركيا مسموحة لمدة 6 أشهر للأجانب (وسنتان للمواطنين الأتراك الحاملين رخصة صادرة من الخارج)، وفق مديرية النفوس والجنسية NVİ. بعد انقضاء الستة أشهر يجب استبدال الرخصة الأجنبية برخصة تركية (tebdil)؛ والقيادة بعدها تُعدّ قيادة بلا رخصة سارية وتُعرّضك لغرامة وحجز المركبة. ابدأ إجراءات الاستبدال قبل انتهاء المدة بوقت كافٍ. لا تخاطر لأن “القيادة بدون رخصة” لها غرامات كبيرة.',
    docs = '["رخصة بلدك.", "جواز/إقامة.", "صور.", "لاستبدال رخصة أجنبية برخصة تركية تحتاج: الرخصة الأجنبية الأصلية + صورة ملونة عنها، ترجمة تركية مصدّقة من النوتر أو القنصلية، وثيقة الهوية/الإقامة، تقرير صحي، وثيقة فصيلة الدم، صورة بيومترية حديثة (خلال 6 أشهر)، شهادة الدراسة (مع ترجمة مصدّقة إن كانت أجنبية)، وثيقة السجل العدلي، ودفع الرسوم."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'car-drive-with-foreign-license';

UPDATE consultant_scenarios SET
    description = 'المدة القصوى لبقاء سيارة بلوحة أجنبية في تركيا هي 730 يوماً (سنتان) للمقيمين خارج المنطقة الجمركية التركية (بمن فيهم المواطنون الأتراك المقيمون في الخارج ومزدوجو الجنسية وحاملو البطاقة الزرقاء، والمتقاعدون منهم). أما الأجنبي غير حامل البطاقة الزرقاء فالمدة الممنوحة لسيارته لا تتجاوز مدة إقامته المشروعة في تركيا. ويُشترط لإدخال السيارة أن تكون قد أقمت فعلياً 185 يوماً على الأقل خارج تركيا خلال السن',
    steps = '["قبل إدخال السيارة: تحقق من أهلية المالك وشروط الإقامة خارج تركيا والوثائق المطلوبة.", "تأكد من التأمين (Sigorta) وأنه يغطي داخل تركيا.", "عند الدخول: احتفظ بكل أوراق الجمارك/المهلة الممنوحة للسيارة.", "راقب تاريخ انتهاء المهلة. غرامات التجاوز لعام 2026 (وزارة التجارة): 2,988 ليرة لتجاوز حتى شهر، 5,976 ليرة حتى شهرين، 8,964 ليرة حتى ثلاثة أشهر. والأخطر: السيارة التي لا تُخرَج في مهلتها ولا يُقدَّم لها طلب تمديد تخضع لأحكام التصفية الجمركية (tasfiye) وقد تفقدها نهائياً. التمديد ممكن: قدّم للجمارك ما يثبت استمرار وضعك (تجديد الإقامة أو إذن العمل) قبل انتهاء المهلة.", "قبل الخروج/التمديد: استعلم من الجمارك عن الإجراء الصحيح."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'car-foreign-vehicle-duration';

UPDATE consultant_scenarios SET
    cost = 'الغرامة الأساسية للمرور من طريق أو جسر مأجور بدون دفع هي أربعة أضعاف رسم المرور (المادة 30 من القانون 6001). لكن القانون يمنحك نافذتين: إذا دفعت رسم المرور نفسه خلال 15 يوماً من تاريخ المرور فلا تُفرض عليك أي غرامة إطلاقاً؛ وإذا فاتتك الخمسة عشر يوماً ودفعت خلال 45 يوماً من تاريخ المرور رسم المرور + ضعفاً واحداً منه كغرامة، اعتُبرت الغرامة ضعفاً واحداً فقط بدل أربعة ولا يُرسَل لك تبليغ. لذلك افحص',
    description = 'غرامة المرور بدون دفع ورسم المرور يجب دفعهما خلال شهر من التبليغ؛ وبعد ذلك يُحالان إلى دائرة الضرائب للتحصيل الجبري بموجب القانون 6183 مع زيادات التأخير. والأهم: لا يُجرى الفحص الفني للسيارة ولا يُقبل بيعها أو نقل ملكيتها قبل تسديد رسم المرور والغرامة (المادة 30/4 من القانون 6001). الأفضل أن تراقب HGS دورياً وتدفع فوراً بعد السفر أو عند الاشتباه بوجود مخالفة.',
    last_update = '2026-07'
WHERE id = 'car-hgs-payment';

UPDATE consultant_scenarios SET
    legal = 'القانون 197 لضريبة المركبات (MTV). ملاحظة مهمة: المادة 4/ج تعفي من الضريبة نهائياً المركبات المسجّلة باسم شخص نسبة إعاقته 90% فأكثر، وكذلك المركبات المعدّلة خصيصاً لتناسب حالة ذوي الإعاقة الآخرين — إعفاء كامل وسنوي يُطلب من دائرة الضرائب بتقرير الإعاقة.',
    steps = '["تحقق من وجود MTV مستحقة على مركبتك عبر بوابة الاستعلام الرسمية/البنك.", "ادفع في موعدها: ضريبة MTV تُدفع كل سنة على قسطين متساويين في شهر كانون الثاني (Ocak) وشهر تموز (Temmuz)، وفق المادة 9 من القانون 197. وإذا سجّلت سيارة لأول مرة خلال العام، فالقسط الذي فات موعده يُدفع خلال شهر من تاريخ التسجيل. أما عند البيع أو نقل الملكية في كانون الثاني أو تموز فتُدفع الضريبة قبل إتمام المعاملة.", "احتفظ بإيصال الدفع، خصوصاً عند بيع/شراء سيارة.", "إذا اشتريت سيارة مستعملة: اسأل عن ديون MTV السابقة.", "ضع تذكيراً لأن الضريبة تتكرر سنوياً."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'car-mtv';

UPDATE consultant_scenarios SET
    steps = '["ابدأ مع المحاسب بتقييم الوضع: هل توجد ديون/قضايا/SGK/ضرائب غير مدفوعة؟", "أوقف أو صفِّ النشاط بشكل منظم (إنهاء عقود، تسوية مستحقات، إغلاق حسابات إن لزم).", "نفّذ إجراءات الإغلاق/التصفية وفق نوع الشركة (LTD/شخصية) عبر القنوات الرسمية والسجل التجاري.", "أغلق الالتزامات الضريبية والدفاتر رسمياً ضمن المهلة: إشعار ترك النشاط يجب تقديمه لمصلحة الضرائب خلال شهر واحد من تاريخ الواقعة (المادة 168 من قانون الإجراءات الضريبية 213). وفي التصفية لا يجوز توزيع ما تبقى من أموال الشركة قبل مرور ثلاثة أشهر على النداء الثالث للدائنين (المادة 543 من قانون التجارة 6102). لا تعتمد على “نوقفها وخلاص”.", "احتفظ بوثائق الإغلاق النهائية وأي إشعارات من الضرائب/السجل."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'company-closure';

UPDATE consultant_scenarios SET
    tip = 'أخطر شيء ليس الغرامة بل المسؤولية الشخصية: بموجب المادة 35 من القانون 6183، يُسأل شركاء الشركة المحدودة شخصياً ومباشرة عن ديون الدولة (ضرائب/SGK) التي تعذّر تحصيلها من الشركة، كل بنسبة حصته، وتُلاحق أموالهم الخاصة. وإذا بعت حصتك تبقى مسؤولاً بالتضامن عن الديون السابقة للبيع. لا تضع اسمك شريكاً في شركة لا تتابع التزاماتها الشهرية.',
    last_update = '2026-07'
WHERE id = 'company-monthly-obligations';

UPDATE consultant_scenarios SET
    cost = 'رأس المال: الحد الأدنى القانوني لشركة LTD هو 50,000 ليرة منذ 1/1/2024 (المادة 580 من قانون التجارة 6102، بقرار رئاسي رقم 7887) + رسوم تسجيل/غرفة + محاسب شهري + ضرائب/دفاتر (تختلف حسب الولاية والنشاط). وإذا كان هدفك إذن عمل كشريك فمعايير وزارة العمل تطلب رأس مال مدفوع 500,000 ليرة.',
    steps = '["حدد النشاط (NACE) بدقة واختر عنواناً صالحاً للتسجيل (مكتب/عنوان شركة مقبول).", "ابدأ عبر MERSIS لتجهيز بيانات الشركة والمسودة الأساسية (عقد تأسيس/نظام).", "اعتمد المحاسب (Mali Müşavir) لأنه سيقود جزءاً كبيراً من التسجيلات والضرائب.", "أنجز التوقيعات/النوتر (تواقيع المدير/مدراء) ثم تابع إجراءات السجل التجاري/الغرفة.", "افتح ملف ضريبي في مصلحة الضرائب وفعّل الدفاتر/اللوحات/الفواتير الإلكترونية حسب النشاط.", "افتح حساباً بنكياً للشركة، وجهّز قنوات الدفع الرسمية.", "فعّل SGK للموظفين إن وُجدوا — ولاحظ أن تأمينك أنت (Bağ-Kur 4/b) كشريك في شركة محدودة يبدأ إلزامياً من تاريخ قيد الشركة في السجل التجاري حتى لو لم يكن لديك أي موظف (المادة 7/ب من قانون 5510)، بحد أدنى ≈ 11,808 ليرة شهرياً في 2026."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'company-setup';

UPDATE consultant_scenarios SET
    steps = '["اجمع الأدلة أولاً: الفاتورة أو إثبات الدفع + صور/فيديو العيب + محادثات/إيميلات + رقم طلب/شحنة.", "جرّب الحل الودي بشكل مكتوب (رسالة للمتجر) واطلب حل ضمن مهلة واضحة؛ هذا يساعدك لاحقاً كدليل.", "حدد طلبك بدقة: إرجاع مبلغ، استبدال، إصلاح، أو تعويض (ولا تكتب طلباً عاماً).", "قدّم الطلب عبر e-Devlet. المسار يتحدد بقيمة النزاع: إذا كانت أقل من 186,000 ليرة (حدّ عام 2026) فتقديم الطلب إلى لجنة تحكيم المستهلك İl/İlçe Tüketici Hakem Heyeti إلزامي — لا تستطيع رفع دعوى مباشرة والمحكمة سترد دعواك. وإذا بلغت 186,000 ليرة أو تجاوزتها فالمسار هو محكمة المستهلك Tüketici Mahkemesi. وتُقدَّم الشكوى إلى لجنة محل إقامتك أو مكان إتمام عملية الشراء.", "ارفع كل الملفات كـPDF/صور واضحة، واكتب ملخصاً زمنياً: متى اشتريت؟ ماذا حدث؟ ماذا طلبت؟ ماذا ردّوا؟", "تابع رقم الطلب وكن جاهزاً لطلب مستند إضافي، واحتفظ بنسخة من كل ما رفعته. اللجنة ملزمة بالبت في الطلب خلال ستة أشهر كحد أقصى. وإذا صدر القرار ضدك، لديك أسبوعان فقط من تاريخ تبليغ القرار للاعتراض عليه أمام محكمة المستهلك (Tüketici Mahkemesi) — بعدها يصبح القرار نهائياً."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'consumer-complaint';

UPDATE consultant_scenarios SET
    description = 'تسجيل قيدك في النفوس التركية (العنوان). أصحاب الإقامات والكملك مجبرون قانونياً على تحديث العنوان خلال عشرين يوم عمل من الانتقال (وليس عشرين يوماً تقويمياً).',
    legal = 'قانون خدمات النفوس رقم 5490 (المادة 50/3) يفرض تبليغ العنوان خلال عشرين يوم عمل (وليس عشرين يوماً تقويمياً)، وتُفرض غرامة إدارية على من لا يبلّغ خلال المهلة، وغرامة أكبر على من يقدّم بياناً مخالفاً للحقيقة (المادة 68).',
    steps = '["استخراج عقد الإيجار باسمك وتوثيقه عند النوتير.", "نقل فواتير (كهرباء أو ماء أو غاز) باسمك.", "حجز موعد عبر موقع إدارة النفوس (NVİ) أو عبر Nüfusmatik في البلدية. وإذا كنت من حاملي الكملك (الحماية المؤقتة): تبليغ النفوس وحده لا يكفي — لائحة الحماية المؤقتة (المادة 33) تُلزمك بالإقامة في الولاية التي حددتها إدارة الهجرة وبتبليغ تغيّر عنوانك للولاية/إدارة الهجرة خلال عشرين يوم عمل. الانتقال إلى ولاية أخرى دون تسوية وضعك مع إدارة الهجرة أولاً قد يؤدي إلى تقييد حقوقك وخدماتك (المادة 35).", "أخذ العقد والفواتير إلى دائرة النفوس وإتمام التثبيت."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'daily-address';

UPDATE consultant_scenarios SET
    cost = 'مجاني في معظم البنوك. مجاني في معظم البنوك. بعض البنوك قد تشترط إيداعاً مبدئياً أو حداً أدنى للرصيد — اسأل الفرع عن قيمته قبل فتح الحساب لأنه يختلف من بنك لآخر ولا توجد جهة رسمية تحدده.',
    last_update = '2026-07'
WHERE id = 'daily-bank-open';

UPDATE consultant_scenarios SET
    legal = 'المهلة تختلف بحسب نوع طلبك: إذا قدّمت شكوى أو طلباً (Şikayet/Öneri) فالجهة ملزمة بالرد المسبب خلال ثلاثين يوماً وفق المادة 7 من قانون حق تقديم العريضة رقم 3071. أما إذا قدّمت طلب معلومات (Bilgi Edinme) فالمهلة خمسة عشر يوم عمل وفق المادة 11 من القانون 4982، وتُمدَّد إلى ثلاثين يوم عمل فقط إذا احتاج الطلب رأي جهة أخرى أو وحدة أخرى، على أن تُبلَّغ بذلك كتابياً قبل انتهاء الخمسة عشر يوم عمل. إذا رُفض طلب المعلومات: يجب — قبل اللجوء إلى القضاء — أن تعترض أمام مجلس تقييم حق الحصول على المعلومات (Bilgi Edinme Değerlendirme Kurulu) خلال خمسة عشر يوماً من تبليغك بالقرار، والمجلس يبتّ خلال ثلاثين يوم عمل. هذا الاعتراض يوقف مدة اللجوء إلى القضاء الإداري (المادة 13 من القانون 4982). ولا تُضيّع المهلة بمراسلة جهات غير مختصة. الفرق الجوهري: CİMER = شكاوى واقتراحات للرئاسة. Dilekçe (عريضة) = طلب رسمي مباشر للجهة المعنية.',
    steps = '["ادخل على cimer.gov.tr أو عبر E-Devlet → CİMER.", "اختر نوع الطلب: شكوى (Şikayet) أو استعلام (Bilgi Edinme) أو اقتراح (Öneri).", "حدد الجهة المعنية بشكواك (مثل: İl Göç İdaresi، Nüfus Müdürlüğü، إلخ).", "اكتب شكواك بالتركية — هذا شرط قانوني لا تفضيل. المادة 3 من قانون حق تقديم العريضة رقم 3071 تنص على أن الأجانب المقيمين في تركيا يستفيدون من هذا الحق بشرط مراعاة المعاملة بالمثل وأن تكون عريضتهم مكتوبة بالتركية؛ والعريضة بغير التركية تخرج من نطاق الضمانة القانونية بما فيها إلزام الجهة بالرد المسبب خلال ثلاثين يوماً. تأكد أيضاً من ذكر اسمك الكامل وعنوان سكنك أو عملك، وأرفق المستندات الداعمة.", "ستحصل على رقم متابعة. المهلة تتبع نوع طلبك: الشكوى/الطلب (Şikayet/Öneri) يُردّ عليها خلال ثلاثين يوماً بموجب المادة 7 من القانون 3071، أما طلب المعلومات (Bilgi Edinme) فمهلته خمسة عشر يوم عمل بموجب المادة 11 من القانون 4982 (قابلة للتمديد إلى ثلاثين يوم عمل بإبلاغ مسبب).", "ملاحظة: BİMER (Başbakanlık İletişim Merkezi) كان النظام القديم قبل 2018 — تم دمجه في CİMER بعد التحول للنظام الرئاسي. إذا سمعت أحداً يذكر BİMER فهو يقصد CİMER."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'daily-cimer';

UPDATE consultant_scenarios SET
    docs = '["رقم الهوية الخاص بك + حساب e-Devlet: إن كنت ما زلت أجنبياً فهو رقم الهوية الأجنبي (Yabancı Kimlik Numarası) الذي يبدأ بـ99 والمدوّن على إقامتك أو كملكك — وهو الرقم الذي تدخل به إلى e-Devlet ولست بحاجة إلى رقم TC كيمليك لمتابعة ملفك.", "رقم الطلب/رقم ملف الجنسية إن كان لديك (Başvuru Numarası).", "هوية/إقامة أو جواز (قد تُطلب عند المراجعة المباشرة).", "أي رسائل SMS/إيميل رسمية تخص الملف (إن وجدت)."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'daily-citizenship-status';

UPDATE consultant_scenarios SET
    description = 'الاستثمار/التداول قد يكون متاحاً عبر منصات مرخصة محلياً، لكن استخدام العملات الرقمية كوسيلة دفع محظور تماماً في تركيا: تنص المادة 3 من «لائحة عدم استخدام الأصول الرقمية في المدفوعات» (الجريدة الرسمية 16/4/2021، العدد 31456) على أنه «لا يجوز استخدام الأصول الرقمية في المدفوعات بشكل مباشر أو غير مباشر». الأهم: اعرف المخاطر وكن جاهزاً لإثبات مصدر الأموال عند التحويل للبنوك.',
    steps = '["إذا قررت التداول: منذ 2/7/2024 (القانون 7518) صارت منصات الأصول الرقمية العاملة في تركيا خاضعة لترخيص ورقابة هيئة أسواق المال SPK. قبل أن تودع أي مبلغ، تحقّق من اسم المنصة في القوائم الرسمية المنشورة على موقع الهيئة (spk.gov.tr → «kripto varlık hizmet sağlayıcılar»): قائمة العاملين، قائمة من أعلن التصفية، وقائمة من هم قيد التصفية. المنصة غير المدرجة تعمل خارج الإطار القانوني وأموالك فيها بلا حماية.", "لا تخلط بين “تداول” و“دفع”؛ قواعد الدفع قد تكون مختلفة ومقيّدة.", "احتفظ بسجل عملياتك (إيداع/سحب/صفقات) لأن البنوك قد تسأل عن مصدر الأموال.", "لا تحول مبالغ كبيرة دفعة واحدة لحسابك البنكي بدون تفسير واضح.", "اعتبر التقلبات عالية؛ لا تستخدم أموال الإيجار/المعيشة كاستثمار عالي المخاطر."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'daily-crypto';

UPDATE consultant_scenarios SET
    cost = 'للمواطنين الأتراك: خدمات طبيب العائلة مجانية بنص المادة 5 من القانون 5258. للأجانب: منذ 15/1/2025 استُثنيت الخدمات المقدَّمة للأجانب من قاعدة المجانية، وتُقدَّم بمقابل وفق تعرفة وزارة الصحة (تعديل 26/9/2025 على «أسس وإجراءات تعرفة الأسعار» — راجع المبلغ الساري لدى مركز صحة العائلة قبل المراجعة). لحاملي كملك الحماية المؤقتة: تُطبَّق المادة 27 من لائحة الحماية المؤقتة (النافذة من 1/1/2026) — «حصة مشاركة» بمقادير SUT، ولا يجوز أن تتجاوز أسعار الخدمة مقادير SUT، ومن يُثبَت عدم قدرته على الدفع تُغطّى تكاليفه من صندوق التضامن الاجتماعي وتُعاد إليه حصص المشاركة عند طلبه. عدم امتلاك تأمين لا يعني أن الخدمة «غير متاحة»: التسجيل يتم على أساس العنوان، ومن يراجع مركزاً غير مركزه يُخدَم بصفة «ضيف» (misafir) ولا يجوز لطبيب العائلة نفسه أن يطلب منه أجراً عن ذلك.',
    description = 'نظام طبيب العائلة (Aile Hekimliği) هو الرعاية الصحية الأولية في تركيا. التسجيل لدى طبيب عائلة يتم على أساس عنوان سكنك المسجّل لدى مديرية الصحة، وليس على أساس امتلاك تأمين SGK/GSS. لكن انتبه: بتعديل 15/1/2025 (القانون 7538 المعدِّل للمادة 5 من القانون 5258) استُثنيت «الخدمات المقدَّمة للأجانب» من قاعدة المجانية، فصارت خدمات طبيب العائلة للأجانب تُقدَّم بمقابل وفق تعرفة تحدّدها وزارة الصحة. أما حاملو كملك الحماية المؤقتة فيخضعون للمادة 27 من لائحة الحماية المؤقتة (بصيغتها النافذة من 1/1/2026): تُستوفى منهم «حصة مشاركة» بمقادير بلاغ التطبيق الصحي SUT، ومن يُثبَت عدم قدرته على الدفع تُغطّى تكاليفه من صندوق التضامن الاجتماعي وتُعاد إليه حصص المشاركة عند طلبه — فلا تمتنع عن مراجعة طبيب العائلة بسبب الكلفة.',
    legal = 'الشرط الأساسي: تأمين SGK أو GSS ساري. لا تنصّ لائحة تطبيق طب العائلة على أي شرط تأمين ولا على استثناء حاملي الإقامة قصيرة الأمد: التسجيل يتم على أساس منطقة السكن، واختيار الطبيب حرّ دون قيد جغرافي، ومن يقيم في تركيا بصفة مؤقتة «يتلقّى الخدمة الصحية من أقرب طبيب عائلة بصفة ضيف (misafir)» ولا يجوز للطبيب أن يطلب منه أجراً عن ذلك. الفرق الحقيقي هو أن الخدمات المقدَّمة للأجانب صارت بمقابل وفق تعرفة وزارة الصحة منذ 15/1/2025، لا أنها ممنوعة عليهم. اعتباراً من 1/1/2026 (تعديل المادة 27 من لائحة الحماية المؤقتة، الجريدة الرسمية 28/11/2025 رقم 33091): لم تُلغَ الخدمة الصحية لحاملي الكملك، بل صار يُستوفى منهم «حصة مشاركة» (katılım payı) بنفس مقادير بلاغ التطبيق الصحي (SUT) المطبّقة على المؤمَّنين. ومن يُثبَت أنه لا يملك القدرة على الدفع، تُغطّى تكاليف علاجه من صندوق التضامن الاجتماعي (SYDTF)، وتُعاد إليه حصص المشاركة التي دفعها عند طلبه ذلك عبر وقف التضامن الاجتماعي في منطقته. لا يوجد شرط قانوني بالحصول على SGK عبر العمل أو دفع اشتراكات GSS للحفاظ على الأهلية.',
    last_update = '2026-07'
WHERE id = 'daily-family-doctor';

UPDATE consultant_scenarios SET
    legal = 'إذا لم تحضر في موعدك فلن يُعالَج طلبك. وبحسب الأسئلة الشائعة لإدارة الهجرة: «يمكنك أخذ موعد جديد وحضوره إن كانت مدتك القانونية ما تزال سارية». أما إذا انتهت مدة إقامتك القانونية قبل الموعد الجديد فأنت في حالة مخالفة تأشيرة/إقامة تترتب عليها غرامة وإجراءات إضافية — لذلك تحقّق من تاريخ انتهاء مدتك القانونية قبل أي إلغاء أو تأجيل. التبليغات بموجب القانون 6458 تتم وفق قانون التبليغات رقم 7201 (المادة 100 من القانون 6458): تُبلَّغ القرارات إلى الأجنبي نفسه أو ممثله القانوني أو محاميه. التبليغ الإلكتروني عبر UETS إلزامي فقط للجهات المعدَّدة في المادة 7/أ من القانون 7201 (المؤسسات العامة، الأشخاص الاعتبارية الخاصة، الكتّاب بالعدل، المحامون…)؛ أما الشخص الطبيعي فلا يُمنح عنوان تبليغ إلكتروني إلا بناءً على طلبه. لذلك حافظ على صحة عنوانك المسجَّل ولا تعتمد على متابعة حساب UETS وحده.',
    last_update = '2026-07'
WHERE id = 'daily-goc-appointment';

UPDATE consultant_scenarios SET
    steps = '["قدّم شكوى أولاً لخدمة العملاء (مكتوبة عبر التطبيق أو الموقع)", "إذا لم تُحل خلال 15 يوماً، قدّم شكوى في BTK (هيئة تنظيم الاتصالات)", "الشكوى في BTK عبر: btk.gov.tr أو تطبيق BTK", "يمكنك أيضاً الشكوى عبر CİMER", "لإلغاء اشتراك ضمن التزام (Taahhüt): بدل الإلغاء محدَّد بسقف قانوني ولا يساوي «باقي قيمة العقد». وفق المادة 12/5 من لائحة حقوق المستهلك في قطاع الاتصالات، لا يجوز أن يتجاوز المبلغ المطلوب منك مجموع ما لم يُحصَّل من قيمة الخصومات والجهاز والمزايا التي حصلت عليها؛ وإن كان مجموع الأقساط غير المستحقة حتى نهاية مدة الالتزام أقل من ذلك، فالمبلغ الأقل هو المعتمد. اطلب من الشركة كتابياً بيان طريقة احتساب المبلغ، واعترض عبر نظام شكاوى الشركة ثم BTK إن تجاوزت السقف."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'daily-internet-telecom';

UPDATE consultant_scenarios SET
    legal = 'قنوات بلاغ رسمية ضمن منظومة الأمن/الطوارئ. مهم: خدمات الحماية ودور الإيواء (kadın konukevi) تُقدَّم للنساء الأجنبيات «دون تمييز بسبب الوضع القانوني أو الجنسية» بحسب وزارة الأسرة والخدمات الاجتماعية — أي أن انتهاء الإقامة أو الكملك لا يمنعك من طلب الحماية. إضافة إلى 112 وتطبيق KADES، يمكن الاتصال بخط الدعم الاجتماعي 183 الذي ينقل الحالة فوراً إلى الشرطة أو الجندرما.',
    last_update = '2026-07'
WHERE id = 'daily-kades';

UPDATE consultant_scenarios SET
    legal = 'حاملو الإقامة السياحية: يجب أن يكون لديهم تأمين صحي خاص (شرط الإقامة أصلاً). لا يحق لهم استخدام SGK إلا إذا كانوا يعملون بشكل رسمي. حاملو الكملك: اعتباراً من 1/1/2026 لم تُوقَف التغطية الصحية، لكن صار يُستوفى منهم «حصة مشاركة» (katılım payı) بمقادير بلاغ التطبيق الصحي SUT نفسها. ومن يُثبَت عدم قدرته على الدفع تُغطّى تكاليف علاجه من صندوق التضامن الاجتماعي (SYDTF)، ولا يجوز له مراجعة المشافي الخاصة مباشرة إلا في الحالات الطارئة والاضطرارية. لا يشترط القانون الحصول على SGK عبر العمل ولا شراء تأمين خاص.',
    last_update = '2026-07'
WHERE id = 'daily-mhrs-booking';

UPDATE consultant_scenarios SET
    steps = '["حدد هل تحتاج: (1) ترجمة محلفة + تصديق نوتر، أم (2) تصديق توقيع/تعهد.", "إذا كانت ترجمة: اختر ترجماناً محلفاً ثم خذ الترجمة للنوتر للتصديق.", "اذهب للنوتر مع الهوية والأصل والنسخ. وإن كنت لا تتقن التركية، فالمادة 74 من قانون النوتر توجب حضور مترجم محلّف معك أثناء المعاملة (وكالة، تعهد، تصديق توقيع) وإلا لن تُنجَز؛ اسأل النوتر مسبقاً عن المترجمين المعتمدين لديه وعن أجرهم.", "ادفع الرسوم واستلم النسخة المصدّقة."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'daily-notary';

UPDATE consultant_scenarios SET
    legal = 'القانون يُلزم بتحديث العنوان خلال 20 يوم عمل من الانتقال (المادة 50/3 من القانون 5490). لحاملي إذن الإقامة: عدم التحديث يؤدي لغرامة مالية وقد يؤثر على تجديد الإقامة. أما حاملو كملك الحماية المؤقتة فيبلّغون تغيير العنوان خلال 20 يوم عمل للجهة التي تحددها الولاية/إدارة الهجرة (المادة 33/2-د من لائحة الحماية المؤقتة)، وعدم الالتزام قد يؤدي — بحسب المادة 35 — إلى إنذار ثم تقييد كلي أو جزئي للخدمات والحقوق الممنوحة لك، باستثناء التعليم والإسعاف الطارئ.',
    steps = '["ادخل على نظام الحجز الإلكتروني الرسمي: randevu.nvi.gov.tr أو عبر E-Devlet → Nüfus ve Vatandaşlık İşleri → Randevu.", "اختر نوع المعاملة (تثبيت عنوان، تغيير عنوان، استخراج وثيقة).", "اختر المديرية الأقرب لعنوانك وحدد الموعد المتاح.", "اذهب في الموعد مع المستندات المطلوبة.", "بديل: أجهزة Nüfusmatik المتوفرة في بعض البلديات ومراكز التسوق لبعض المعاملات البسيطة."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'daily-nvi-appointment';

UPDATE consultant_scenarios SET
    tip = 'إن كان لديك رقم أجنبي (Yabancı Kimlik No الذي يبدأ بـ99 على الكملك أو بطاقة الإقامة) فهو نفسه رقمك الضريبي منذ 1/7/2010، ولا تحتاج لاستخراج رقم ضريبي منفصل. خدمة «الرقم الضريبي المحتمل» مخصّصة لمن لا يملك رقم هوية أجنبي بعد. احتفظ برقمك في هاتفك دائماً.',
    last_update = '2026-07'
WHERE id = 'daily-tax-number';

UPDATE consultant_scenarios SET
    cost = 'حسب نوع المخالفة: أدنى غرامة في دليل 2026 الرسمي هي 1,000 ليرة (750 ليرة بخصم 25%)، وتصل أعلى الغرامات إلى مئات الآلاف من الليرات. راجع «2026 Yılı Trafik İdari Para Ceza Rehberi» على موقع trafik.gov.tr للمبلغ الدقيق لكل مادة.',
    steps = '["استعلم عن المخالفات عبر e-Devlet → Trafik Cezası Sorgulama", "ادفع خلال شهر واحد من تاريخ التبليغ للحصول على خصم 25% (المهلة كانت 15 يوماً وتم تمديدها إلى شهر اعتباراً من 31/1/2024). ودفعك للمخالفة لا يُسقط حقك في الاعتراض عليها.", "الدفع عبر البنك أو PTT أو e-Devlet مباشرة", "للاعتراض: قدّم طلباً في محكمة الصلح (Sulh Ceza) خلال 15 يوماً", "تابع الاعتراض عبر UYAP"]'::jsonb,
    last_update = '2026-07'
WHERE id = 'daily-traffic-fine';

UPDATE consultant_scenarios SET
    description = 'UETS (Ulusal Elektronik Tebligat Sistemi) هو نظام التبليغات الرسمية الإلكترونية في تركيا. التبليغ الإلكتروني إلزامي للجهات المعدّدة في المادة 7/أ من قانون التبليغات 7201 (المؤسسات العامة، الأشخاص الاعتباريون، النوتر، المحامون…). أما الأفراد فيُمنحون عنوان تبليغ إلكتروني بناءً على طلبهم فقط، ومن لم يطلبه تصله التبليغات بالطريقة الورقية.',
    steps = '["ادخل على E-Devlet → UETS Tebligat Sorgulama لمعرفة إذا كان لديك تبليغات معلقة.", "التبليغ يُعتبر مُستلَماً بعد 5 أيام من إرساله حتى لو لم تقرأه.", "عند استلام تبليغ: اقرأه فوراً واحسب المهلة من تاريخ التبليغ — 7 أيام للطعن على قرار الترحيل أمام المحكمة الإدارية (المادة 53/3 من القانون 6458)، و60 يوماً للطعن على رفض أو إلغاء الإقامة (القاعدة العامة في المادة 7 من قانون القضاء الإداري 2577). انتبه: قرارات الحماية الدولية لها مهل أقصر — 15 يوماً لقرارات المادتين 72 و79 (عدم القبول/التقييم المعجّل) و30 يوماً لسائر قرارات الحماية الدولية (المادة 8", "ما يحدّد وصول التبليغ إلكترونياً ليس حساب E-Devlet بل امتلاك عنوان تبليغ إلكتروني (UETS) يُمنح للأفراد بناءً على طلبهم عبر PTT. إن لم يكن لديك عنوان UETS تصلك التبليغات بالطريقة التقليدية (بريد مسجل أو تسليم شخصي)، حتى لو كان لديك حساب E-Devlet.", "ملاحظة: حتى حاملي الكملك يمكنهم تفعيل E-Devlet عبر مراجعة PTT مع الكملك."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'daily-uets';

UPDATE consultant_scenarios SET
    legal = 'ملفات İcra تبقى مفتوحة حتى يتم تسديد الدين كاملاً أو حتى يسقط بالتقادم. المدة العامة عشر سنوات (المادة 146 من TBK، والمادة 39 من İİK للتنفيذ المستند إلى حكم)، لكن الديون الدورية — كالأجرة وفواتير الاشتراكات والأجور والفوائد — تسقط بخمس سنوات (المادة 147 من TBK). إن كان الدين المطالب به دورياً وأقدم من خمس سنوات فاستشر مختصاً بشأن الدفع بالتقادم. الديون المحكوم بها تُنفَّذ إجبارياً عبر حجز الحسابات والممتلكات.',
    last_update = '2026-07'
WHERE id = 'daily-uyap';

UPDATE consultant_scenarios SET
    legal = 'الأجانب حاملو إذن الإقامة لا يُسجَّلون تلقائياً في GSS: بحسب المادة 61/1-ج من القانون 5510، لا يُعتبر الأجنبي مؤمَّناً في GSS إلا إذا تقدّم بطلب بعد تجاوز إقامته في تركيا سنة كاملة، ويبدأ التأمين من اليوم التالي لتاريخ الطلب — ومن أقام أقل من سنة لا يُعد مؤمَّناً أصلاً. أما حاملو كملك الحماية المؤقتة فليسوا ضمن نظام GSS ولا يتراكم عليهم قسط GSS؛ خدماتهم الصحية تنظّمها المادة 27 من لائحة الحماية ال',
    steps = '["دين الـ GSS (Genel Sağlık Sigortası): ادخل E-Devlet → SGK → GSS Borç Sorgulama. لا يتراكم القسط تلقائياً على الأجنبي: القيد في GSS يبدأ فقط إذا تقدّمت بطلب بعد إتمام سنة إقامة في تركيا (المادة 61/1-ج من القانون 5510). إن ظهر لك دين ولم تتقدّم بأي طلب، راجع SGK لتصحيح القيد بدل دفعه.", "ديون İcra (تنفيذ): ادخل E-Devlet → UYAP → İcra Dosya Sorgulama. أو زُر دائرة التنفيذ بشخصك.", "مستحقات SGK: ادخل E-Devlet → SGK Hizmet Dökümü للتحقق من حالة التأمين والمستحقات.", "ديون ضرائب: İnteraktif Vergi Dairesi أو E-Devlet → Vergi Borç Sorgulama.", "ملاحظة مهمة: دين GSS يمنع الحصول على تأمين صحي حكومي ويمنع تجديد الإقامة في بعض الولايات."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'debt-check';

UPDATE consultant_scenarios SET
    description = 'إجراءات عاجلة إذا رُفض دخولك إلى تركيا في المطار أو المعبر الحدودي. وإن كنت خائفاً على حياتك أو حريتك في البلد الذي ستُعاد إليه فقُلها صراحةً للموظف واطلب تقديم طلب حماية دولية: المادة 8 من القانون 6458 تمنع تفسير شروط الدخول أو تطبيقها بما يعرقل تقديم طلب الحماية الدولية، والمادة 4 تمنع إعادتك إلى مكان تكون فيه حياتك أو حريتك مهدَّدة.',
    steps = '["اطلب معرفة السبب كتابياً (قد يكون حظر دخول سابق أو مشكلة في الفيزا)", "اطلب الاتصال بمحاميك أو بقنصلية بلدك", "إذا كان لديك إقامة سارية، أبرز وثائقها فوراً", "احفظ نسخة من قرار الرفض وسجّل تاريخ تبليغه: لديك ستون يوماً من تاريخ التبليغ الكتابي لرفع دعوى إلغاء أمام المحكمة الإدارية (المادة 7 من القانون 2577). ويمكنك خلال هذه المدة تقديم طلب مكتوب للجهة التي أصدرت القرار أو لرئاستها فيوقف ذلك سريان المهلة (المادة 11)، وإن لم يصلك رد خلال ثلاثين يوماً عُدَّ الطلب مرفوضاً واستأنفت المهلة. أما CİMER فهو سجل شكوى وليس طعناً قضائياً — لا تكتفِ به.", "في حالة الترحيل الفوري، وثّق كل شيء واحتفظ بنسخة من قرار الرفض"]'::jsonb,
    last_update = '2026-07'
WHERE id = 'emergency-airport-denied';

UPDATE consultant_scenarios SET
    docs = '["صورة عن الهوية/الكملك", "تقرير طبي (إن وجد)", "أي دليل على العنف (صور/رسائل) — إن وُجد فقط. المادة 8/3 من القانون 6284 تنص صراحة على أنه لا يُطلب أي دليل أو وثيقة لإصدار أمر الحماية، فلا تؤجّل الطلب لأنك لا تملك تقريراً طبياً أو صوراً."]'::jsonb,
    steps = '["اتصل بالشرطة فوراً على الرقم 155 أو استخدم تطبيق KADES", "اذهب لأقرب مركز شرطة وسجّل بلاغاً رسمياً (Şikâyet)", "اطلب أمر الحماية (Koruma Kararı) من أقرب وأسهل جهة تصلها: قاضي محكمة الأسرة، أو المحافظ/القائمقام (Mülkî Amir)، أو مركز الشرطة/الجندرمة نفسه — المادة 8/1 من القانون 6284 تتيح الثلاثة. وفي الحالات المستعجلة يستطيع آمر الشرطة نفسه أن يتخذ فوراً تدابير الإيواء وإبعاد المعتدي عن المنزل ومنعه من الاقتراب (المادتان 3/2 و5/2)، ثم يُعرض القرار على المحافظ خلال ٤٨ ساعة أو على القاضي خلال ٢٤ ساعة للتصديق.", "تواصل مع خط ALO 183 للإرشاد والدعم النفسي (متاح 24/7)", "إذا لم يكن لديك مكان آمن، اطلب إيواء في مركز حماية المرأة (Kadın Konukevi)"]'::jsonb,
    last_update = '2026-07'
WHERE id = 'emergency-domestic-violence';

UPDATE consultant_scenarios SET
    tip = 'التهديد حتى عبر الإنترنت جريمة يُعاقب عليها القانون التركي. احتفظ بكل الأدلة ولا تحذف شيئاً — لكن انتبه للمهلة: جرائم التحرش (المادة 105) والتهديد بالإضرار بالمال أو بشرّ آخر (المادة 106/1) تُلاحق بالشكوى فقط، ولديك ستة أشهر من يوم علمك بالفعل وبهوية الفاعل لتقديم الشكوى، وبعدها لا يجوز التحقيق ولا المحاكمة (المادة 73 من قانون العقوبات). قدّم الشكوى إلى النيابة العامة أو الشرطة/الجندرمة ولا تكتفِ بـ CİMER.',
    last_update = '2026-07'
WHERE id = 'emergency-harassment-threat';

UPDATE consultant_scenarios SET
    steps = '["سجّل طفلك عند طبيب العائلة (Aile Hekimi) — التطعيمات مجانية", "التطعيمات تُعطى مجاناً وفق جدول وزارة الصحة وهي موصى بها بشدّة، لكنها ليست إلزامية قانوناً: المحكمة الدستورية التركية (الهيئة العامة، قرار Halime Sare Aysal رقم 2013/1789 بتاريخ 11/11/2015) قضت بأنه لا يوجد في القانون رقم 1593 نصّ يصلح سنداً قانونياً للتطعيم الإجباري.", "تابع مواعيد التطعيم عبر تطبيق e-Nabız", "إذا فاتتك تطعيمات، اذهب لأقرب مركز صحي (ASM) لتعويضها", "احتفظ بدفتر التطعيم (Aşı Kartı) — مطلوب للتسجيل في المدرسة"]'::jsonb,
    last_update = '2026-07'
WHERE id = 'family-child-vaccination';

UPDATE consultant_scenarios SET
    legal = 'قانون الصحة العامة رقم 1593 + المادة 15 من قانون خدمات النفوس رقم 5490 (وجوب التبليغ عن الولادة خلال 30 يوماً داخل تركيا) + المادة 33/2-د من لائحة الحماية المؤقتة (التبليغ خلال 20 يوم عمل للمشمولين بالحماية المؤقتة)',
    steps = '["سجّلي الحمل عند طبيب العائلة أو في مشفى حكومي", "متابعة الحمل مجانية في المشافي الحكومية (حتى بدون تأمين للحوامل)", "اختاري مشفى الولادة مسبقاً واحجزي عبر MHRS", "بعد الولادة: سجّلي المولود في المشفى ثم في النفوس خلال 30 يوماً (المادة 15 من القانون 5490). وإن كنتِ مشمولة بالحماية المؤقتة فالمهلة الملزِمة لكِ أقصر: عليك تبليغ إدارة الهجرة بالولادة خلال 20 يوم عمل (المادة 33/2-د من لائحة الحماية المؤقتة).", "إعانة الولادة (Doğum Yardımı) مخصّصة للمواطنين الأتراك فقط: تشترط وزارة الأسرة والخدمات الاجتماعية أن يكون أحد الوالدين مواطناً تركياً، وأن يكون مقدّم الطلب وصاحب الحق والطفل نفسه مواطنين أتراكاً — فلا تنطبق على الأجانب ولا على حملة البطاقة الزرقاء. إن كنت أجنبية فاسألي مديرية الأسرة والخدمات الاجتماعية في ولايتك عن المساعدات الاجتماعية المتاحة لك بدلاً منها."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'family-pregnancy-birth';

UPDATE consultant_scenarios SET
    legal = 'قانون ملكية الطوابق رقم 634: المدين الأصلي بالعائدات هو مالك الشقة (المادة 20). ومسؤولية المستأجر تضامنية لكنها محدودة بمقدار الأجرة المستحقة عليه، وما يدفعه من عائدات يُخصم من الأجرة (المادة 22). كما تُحتسب على المتأخرات غرامة تأخير 5% شهرياً بحسب المادة 20.',
    last_update = '2026-07'
WHERE id = 'housing-aidat';

UPDATE consultant_scenarios SET
    cost = 'الغرامات محدّدة في المادة 4 من القانون 7464: مئة ألف ليرة عن كل شقة تُؤجَّر سياحياً بلا ترخيص (مع مهلة 15 يوماً لاستخراجه)، وخمسمئة ألف ليرة عند الاستمرار بعد المهلة، ومليون ليرة عند الإصرار. هذه قيم أساسية لعام 2023 تُرفع كل يناير بنسبة إعادة التقييم وفق المادة 17/7 من قانون المخالفات 5326. أما رسوم الترخيص واللوحة فتحددها وزارة الثقافة والسياحة.',
    steps = '["حدد نوع التأجير: أقل من 100 يوم/قصير المدة أم إيجار عادي طويل المدة.", "الترخيص إلزامي وليس اختيارياً: بحسب المادة 3 من القانون 7464، يجب الحصول على «izin belgesi» من وزارة الثقافة والسياحة قبل توقيع أي عقد تأجير سياحي، ويُشترط لتقديم الطلب إبراز قرار صادر بإجماع جميع ملاك الشقق في البناء (oy birliği). كما يُعلَّق «plaket» على مدخل الشقة.", "لا تبدأ الإعلان قبل التأكد من المتطلبات لأن الغرامات قد تكون كبيرة.", "إذا كنت مستأجراً: القانون نفسه يمنعك — المادة 3/7 من القانون 7464 تحظر على من استأجر بيتاً للسكن أن يعيد تأجيره سياحياً لحسابه، وتفرض المادة 4/1-ç غرامة إدارية قدرها مئة ألف ليرة (قيمة أساسية لعام 2023 تُرفع سنوياً) عن كل عقد. المنع قائم حتى لو لم يذكره عقد إيجارك.", "إن قررت المضي: اجعل كل شيء موثقاً (عقود/فواتير/هوية ضيف) ضمن الإطار القانوني."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'housing-airbnb-law';

UPDATE consultant_scenarios SET
    legal = 'المادة 342 من TBK: الحد الأقصى للتأمين = 3 أشهر إيجار. أي مبلغ زائد يحق لك استرداده فوراً. المادة 334 من TBK: المستأجر يعيد المأجور بالحالة التي استلمه بها، لكنه غير مسؤول عن التقادم والتلف الناتج عن الاستعمال المطابق للعقد (الاستهلاك الطبيعي). لا يُخصم الاستهلاك الطبيعي من التأمين، فقط الأضرار الفعلية. فقط الأضرار الفعلية. التأمين يجب أن يُودع في بنك (نظرياً) والفوائد للمستأجر — لكن التطبيق العملي نادر.',
    steps = '["تأكد من أن مبلغ التأمين المدفوع لا يتجاوز 3 أشهر إيجار (الحد القانوني الأقصى — المادة 342 من TBK).", "عند انتهاء العقد: سلّم المنزل نظيفاً مع إصلاح أي أضرار تسببت بها (الاستهلاك الطبيعي ليس ضرراً).", "وثّق حالة المنزل عند التسليم: صوِّر كل غرفة بالفيديو + وقّع محضر تسليم مع المالك. وتذكّر المادة 335 من TBK: المالك ملزم بمعاينة المنزل وقت الاستلام وإبلاغك كتابياً وفوراً بأي نقص أو عيب يحمّلك مسؤوليته، وإن لم يفعل تتحرر من المسؤولية عن كل ما كان يمكن كشفه بالمعاينة العادية. الاستثناء الوحيد: العيوب الخفية التي لا تظهر بالفحص المعتاد تبقى مسؤوليتك، وعلى المالك إبلاغك كتابياً فور اكتشافها. لذلك لا", "اطلب التأمين كتابياً: أرسل إنذاراً عبر نوتير (İhtarname) إذا رفض المالك الإعادة.", "إذا لم يستجب: يمكنك بدء إجراء تنفيذ (İcra takibi) أو رفع دعوى في Sulh Hukuk Mahkemesi. انتبه: في إجراء التنفيذ يكفي أن يعترض المالك خلال مهلته ليتوقف الإجراء (المادة 66 من İİK)، وعندها عليك رفع دعوى «itirazın iptali» خلال سنة من تبليغك الاعتراض (المادة 67). ولا يُحكم عليك بتعويض (لا يقل عن 20%) إلا إذا طلبه الطرف الآخر وثبت أنك بدأت التنفيذ بغير حق وبسوء نية — فلا تخف من المسار إن كانت مطالبتك موث", "ملاحظة مهمة: إذا كان التأمين مودعاً في حساب بنكي وفق المادة 342 من TBK، فالبنك ملزم بإعادته لك بمجرد طلبك إذا لم يُبلغه المالك كتابياً — خلال ثلاثة أشهر من انتهاء العقد — بأنه رفع دعوى أو بدأ إجراء تنفيذ/إفلاس ضدك. قبل ذلك لا يُعيده البنك إلا برضا الطرفين أو بتنفيذ مكتسب القطعية أو بحكم محكمة نهائي."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'housing-deposit';

UPDATE consultant_scenarios SET
    legal = 'المادة 342 من قانون الالتزامات التركي (TBK 6098): في إيجارات السكن والمحال المسقوفة، لا يجوز أن يتجاوز التأمين أجرة ثلاثة أشهر. وإذا اتُفق على دفعه نقداً، يُودَع في حساب توفير لأجل لا يُسحب إلا بموافقة المالك؛ والبنك ملزم بإعادته لك بمجرد طلبك إذا لم يُبلغه المالك كتابياً خلال ثلاثة أشهر من انتهاء العقد بأنه رفع دعوى أو بدأ إجراء تنفيذ ضدك.',
    last_update = '2026-07'
WHERE id = 'housing-depozito-limit';

UPDATE consultant_scenarios SET
    legal = 'المادة 347 من TBK: العقد يتجدد تلقائياً لسنة. المادة 350: إخلاء الحاجة الشخصية (المالك يثبت حاجته). المادة 352: تعهد الإخلاء صالح فقط إذا وُقِّع بعد بدء العقد (ليس مع العقد). المادة 355: المالك الذي يخلي بالحاجة الشخصية ممنوع من تأجيره لغيره لمدة 3 سنوات. إذا تسبّبت خلال سنة إيجارية واحدة في توجيه إنذارين خطيين مُحقّين إليك بسبب عدم دفع الإيجار، يحق للمالك إنهاء العقد عن طريق دعوى قضائية تُرفع خلال شهر واحد من نهاية تلك السنة الإيجارية — وليس الإخلاء المباشر (المادة 352/2 من TBK).',
    steps = '["الإخلاء بسبب عدم الدفع: المالك يبدأ متابعة تنفيذية عبر İcra مع إنذار دفع. انتبه: هناك مهلتان مختلفتان ولا تخلط بينهما — مهلة الدفع 30 يوماً على الأقل في المساكن (المادة 315 من TBK)، أما مهلة الاعتراض (itiraz) على أمر الدفع في دائرة İcra فهي 7 أيام فقط من تاريخ التبليغ (المادة 269 من قانون التنفيذ والإفلاس 2004). إذا لم تعترض خلال 7 أيام ولم تدفع خلال المهلة، تقرر محكمة التنفيذ الإخلاء بناءً على طلب المالك.", "الإخلاء بسبب الحاجة الشخصية (İhtiyaç): المالك يجب أن يثبت حاجته الحقيقية. يتم عبر دعوى في Sulh Hukuk Mahkemesi.", "الإخلاء بنهاية العقد: لا يُخلى المستأجر تلقائياً بانتهاء العقد، والعقد يتجدد تلقائياً لسنة. وبعد انقضاء عشر سنوات من سنوات التمديد (أي مدة العقد الأصلية + 10 سنوات تمديد)، يحق للمالك إنهاء العقد بدون إبداء سبب — لكن بشرط أن يبلغك كتابياً قبل 3 أشهر على الأقل من نهاية كل سنة تمديد لاحقة، وإلا فالإنهاء غير نافذ (المادة 347 من TBK).", "تعهد الإخلاء (Tahliye Taahhüdü): إذا وقّعت تعهداً بالإخلاء في تاريخ محدد، المالك يمكنه استخدامه في İcra — لكن يجب أن يكون مؤرخاً بعد بدء عقد الإيجار.", "في جميع الحالات: لا تخرج من المنزل قبل صدور حكم قضائي نهائي. المالك الذي يقطع الخدمات (كهرباء/ماء) أو يغير القفل يرتكب جريمة.", "المهل القانونية: مهلة الدفع في إنذار عدم الدفع: 30 يوماً على الأقل في المساكن (المادة 315 من TBK)، ومهلة الاعتراض في İcra: 7 أيام. الإخلاء لحاجة المالك الشخصية: لا يوجد «إنذار قبل 3 أشهر» — القانون يوجب على المالك رفع دعوى خلال شهر واحد من نهاية مدة العقد، وتمتد هذه المهلة سنة إيجارية كاملة إذا أبلغك كتابياً خلالها بنيته رفع الدعوى (المادتان 350 و353 من TBK). أما في العقود غير محددة المدة فمهلة الإشعار ثلاثة أشهر لنهاية فترة إيجار مدتها ستة أشهر (المادة 329 من TBK)."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'housing-eviction';

UPDATE consultant_scenarios SET
    legal = 'المادة 344 من TBK (Türk Borçlar Kanunu): الزيادة السنوية لا تتجاوز نسبة TÜFE لـ 12 شهر. ملاحظة: كان هناك سقف مؤقت 25% انتهى في يوليو 2024. حالياً يُعمل بنسبة TÜFE الكاملة. السقف القانوني مُلزِم حتى لو اتفق الطرفان على نسبة أعلى في العقد — الاتفاق الأعلى من TÜFE باطل في حدود الزيادة. استثناء مهم: في العقود التي تتجاوز خمس سنوات أو التي تُجدَّد بعد خمس سنوات، وعند نهاية كل خمس سنوات لاحقة، يحدّد القاضي بدل الإيجار الجديد آخذاً بعين الاعتبار متوسط TÜFE وحالة المأجور وأجور المثل (emsal kira bedelleri) معاً — وقد يتجاوز سقف TÜFE بشكل قانوني (المادة 344/3 من TBK).',
    steps = '["تحقق من نسبة TÜFE المعتمدة لشهر التجديد: ادخل على موقع TÜİK (data.tuik.gov.tr) أو ابحث عن \"TÜFE kira artış oranı\" + الشهر.", "نسبة الزيادة القانونية = متوسط TÜFE لآخر 12 شهراً السابقة لشهر التجديد. لا يوجد رقم واحد يصلح لسنة كاملة، ورقم «~65%» يعود إلى منتصف 2024 لا إلى 2025. السقف القانوني هو «معدل التغير وفق متوسط 12 شهراً» (on iki aylık ortalamalara göre değişim) في مؤشر TÜFE الذي تنشره TÜİK — وهو رقم مختلف عن «التضخم السنوي» المتداول في الأخبار وأعلى منه غالباً — وقد انخفض بشكل متواصل خلال 2025. قبل قبول أي زيادة: استخرج من data.tuik.gov.tr رقم «on iki aylık ortalamalara göre değişim» ال لعام 2026 تعتمد على بيانات TÜİK الشهرية.", "إذا طلب المالك زيادة أعلى: ارفض كتابياً واستشهد بالمادة 344 من قانون TBK.", "لجنة حكم المستهلك (Tüketici Hakem Heyeti) غير مختصة بنزاعات الإيجار بين المستأجر والمالك؛ اختصاصها محصور بمعاملات المستهلك (المادة 66 من القانون 6502). المسار الصحيح: تقديم طلب وساطة (Arabuluculuk) وهو شرط إجباري قبل رفع أي دعوى إيجار منذ 1/9/2023 (المادة 18/B من القانون 6325)، ثم دعوى في Sulh Hukuk Mahkemesi إذا لم يحصل اتفاق.", "إذا رفض المالك التراجع: لا يمكنك رفع الدعوى مباشرة. يجب أولاً التقدّم بطلب وساطة إجبارية (dava şartı arabuluculuk) وفق المادة 18/B من القانون 6325 — والدعوى المرفوعة بدون محضر وساطة تُرَدّ شكلاً. بعد انتهاء الوساطة دون اتفاق، ترفع الدعوى في Sulh Hukuk Mahkemesi مرفقةً بمحضر عدم الاتفاق.", "ملاحظة: العقود الجديدة (أول مرة) لا يسري عليها سقف TÜFE — السقف فقط للتجديد."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'housing-rent-increase';

UPDATE consultant_scenarios SET
    steps = '["ادفع الإيجار دائماً عبر تحويل بنكي/حوالة (EFT/Havale/FAST حسب البنك) إلى حساب المالك أو الحساب المحدد في العقد.", "اكتب في خانة الشرح: “Kira + شهر/سنة + عنوان إن أمكن” لتكون الدفعة واضحة عند المحكمة.", "احتفظ بكشوف الحساب/الإيصالات شهرياً (PDF) ولا تعتمد على لقطة شاشة فقط.", "لا تدفع الإيجار نقداً حتى لو طلب المالك ذلك: منذ 17/10/2024 (التبليغ العام رقم 328 لضريبة الدخل) صار توثيق كل مقبوضات ومدفوعات الإيجار عبر البنك أو PTT إلزامياً مهما كان المبلغ، ويشمل الالتزام المستأجر والمالك معاً حتى لو لم يكونا مكلَّفين ضريبياً، والمخالفة تعرّض كلاً منهما لغرامة خاصة (özel usulsüzlük cezası) بنسبة 10% من مبلغ كل عملية. وإن رفض المالك إعطاءك IBAN، اذهب إلى فرع البنك وأودع المبلغ في حسابه مع ذكر رقم هويته/رقمه الضريبي واسمه وكتابة الشرح «kira ödemesi» — تعتبر مصلحة الضرائب هذا استيفاءً للالتزام.", "إذا كان هناك زيادة نزاعية: ادفع الجزء “غير المتنازع” نظامياً وتجنب قطع الدفع كلياً."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'housing-rent-payment-legal';

UPDATE consultant_scenarios SET
    legal = 'المادة 352/1 من TBK: التعهد صالح فقط إذا كان مكتوباً + موقعاً من المستأجر + بتاريخ إخلاء محدد + صادراً بعد تسليم المأجور فعلياً للمستأجر. التعهد الموقّع بنفس تاريخ العقد يُعَدّ باطلاً في الاجتهاد القضائي المستقر. تحذير مهم: التعهد بتاريخ فارغ ليس حماية لك — محكمة التمييز (Yargıtay) كثيراً ما تعتبر أن من وقّع ورقة فارغة قَبِل ملء التاريخ لاحقاً، وعبء إثبات العكس عليك وهو صعب؛ فلا توقّع ورقة فارغة أ تعهد بتاريخ فارغ أو بنفس تاريخ العقد = باطل. حتى لو كان التعهد صحيحاً، المالك يجب أن يستخدمه خلال شهر واحد من تاريخ الإخلاء المحدد فيه وإلا يسقط.',
    steps = '["هل وُقِّع التعهد أثناء توقيع العقد أم بعده؟ إذا وُقِّع بنفس تاريخ العقد أو قبل تسليم المأجور → باطل قانونياً (المادة 352/1 من TBK).", "إذا كان التعهد صحيحاً (وُقِّع بعد بدء العقد): المالك يمكنه تقديمه في İcra Müdürlüğü لطلب الإخلاء عند حلول التاريخ.", "لديك 7 أيام للاعتراض على طلب الإخلاء في İcra. أسباب الاعتراض: التعهد مُزوَّر، وُقِّع تحت إكراه، التاريخ مزور.", "إذا اعترضت: تُحال القضية للمحكمة للفصل.", "إذا لم تعترض خلال 7 أيام: يصبح قرار الإخلاء نهائياً.", "حماية نفسك: صوِّر التعهد عند التوقيع. لا توقع تعهداً بتاريخ فارغ (مفتوح)."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'housing-tahliye-undertaking';

UPDATE consultant_scenarios SET
    steps = '["قبل الشراء: تحقق من أهلية العقار للبرنامج. منذ تعديل 12/12/2023 (قرار رئاسي 7938) لم يعد أي عقار مقبولاً: يجب أن يكون العقار قد أُسِّس عليه \"ملكية طوابق\" (Kat Mülkiyeti) أو \"حق ارتفاق طوابق\" (Kat İrtifakı)، أو أن يكون أرضاً بصفة \"أرسا\" (arsa) قائم عليها بناء فعلاً. الأراضي الفارغة والأراضي الزراعية لا تؤهّل للجنسية مهما بلغت قيمتها. وتحقق أيضاً من تاريخ الملكية وقيود الطابو وعدم وجود رهن أو حجز.", "اعتمد تقييم عقاري رسمي مطابق للشروط، وتأكد أن القيمة تلبي الحد الأدنى المطلوب وقت التقديم.", "نفّذ الدفع عبر تحويلات بنكية وفق الإطار المطلوب، ثم استخرج وثيقة تحويل العملة/التحويل البنكي المطلوبة (مثل DAB) من البنك.", "أكمل نقل الملكية في الطابو، واطلب إضافة تعهد/قيد “عدم البيع لمدة 3 سنوات”.", "جهّز ملف المستثمر والعائلة (زوج/زوجة وأطفال دون 18) مع ترجمات/أبوستيل حسب بلد الإصدار.", "تابع المراحل الإدارية (إقامة مستثمر/تقديم ملف الجنسية) حتى القرار النهائي."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'investor-citizen';

UPDATE consultant_scenarios SET
    steps = '["استخرج رقم ضريبي (Vergi Numarası) من مكتب الضرائب", "افتح حساباً بنكياً تركياً، ثم — وهذه خطوة إلزامية منذ 24/1/2022 — بِع العملة الأجنبية للبنك المركزي عن طريق بنكك واستخرج \"وثيقة شراء العملة\" (Döviz Alım Belgesi - DAB) باسمك وباسم العقار. مديرية الطابو لا تُتمّ نقل الملكية للأجنبي بدون هذه الوثيقة (تعميم المديرية العامة للطابو والمساحة).", "اختر العقار وتفاوض على السعر", "تحقق من صحة الطابو (سند الملكية) عبر الموقع الرسمي أو المحامي", "وقّع عقد البيع الأولي عند النوتر (Noter)", "احصل على تقرير تقييم عقاري (Değerleme Raporu) من شركة معتمدة من SPK", "قدّم طلب نقل الملكية في مديرية الطابو (Tapu Müdürlüğü)", "ادفع رسم الطابو: القانون رقم 492 (التعرفة 4، البند 20/أ) يفرضه بنسبة 2% على البائع و2% على المشتري كلٌّ على حدة (أي 4% إجمالاً)، ويُحسب على ثمن البيع المصرَّح به على ألا يقلّ عن القيمة الضريبية للعقار (Emlak Vergisi Değeri) — وليس على قيمة تقرير التقييم. اتفق كتابةً مع البائع على من يتحمّل حصّته.", "استلم الطابو الجديد باسمك"]'::jsonb,
    last_update = '2026-07'
WHERE id = 'investor-property-buying-process';

UPDATE consultant_scenarios SET
    steps = '["وثّق المشكلة بالصور والمراسلات", "أرسل إنذاراً رسمياً عبر النوتر (İhtarname) للطرف الآخر", "إذا لم يُستجب لإنذارك، فتحقق أولاً من المسار الصحيح لنزاعك: نزاعات عين العقار (إبطال/تسجيل الطابو) لا تخضع لشرط الوساطة الإلزامية (المادة 73/أ-1/د من القانون 6502)، بينما نزاعات الإيجار وإزالة الشيوع وملكية الطوابق وحق الجوار تخضع لها (المادة 18/ب من القانون 6325). ابدأ بالمسار الصحيح مباشرة ولا تضيّع أشهراً في وساطة غير مطلوبة.", "إن كانت قيمة نزاعك أقل من الحد السنوي (186,000 ليرة لعام 2026 وفق تعميم وزارة التجارة المنشور في الجريدة الرسمية 23/12/2025 العدد 33116) فالمراجعة إلزامية أمام لجنة تحكيم المستهلك في الولاية أو القضاء (Tüketici Hakem Heyeti) ولا يجوز رفع الدعوى في محكمة المستهلك أصلاً (المادة 68 من القانون 6502). وإن تجاوزت القيمة هذا الحد فلا يجوز اللجوء للجنة، وترفع الدعوى في محكمة المستهلك.", "تابع القضية عبر UYAP"]'::jsonb,
    tip = 'الوساطة (Arabuluculuk) ليست إلزامية في كل نزاع عقاري: القانون 6502 (المادة 73/أ-1/د) يستثني صراحةً "النزاعات الناشئة عن عين العقار" — أي نزاعات الملكية والطابو مع البائع أو المطوّر — من شرط الوساطة، كما يستثني ما يدخل في اختصاص لجنة تحكيم المستهلك. أما الحالات التي تكون فيها الوساطة شرطاً للدعوى فهي محدَّدة في المادة 18/ب من القانون 6325: نزاعات الإيجار، وقسمة الأموال وإزالة الشيوع، ونزاعات قانون ملكية الطوابق، ونزاعات حق الجوار. استشر محامياً لتحديد أي مسار ينطبق على نزاعك قبل أن تخسر وقتاً.',
    last_update = '2026-07'
WHERE id = 'investor-property-dispute';

UPDATE consultant_scenarios SET
    cost = 'قيمة العقار + رسوم/ضرائب طابو + تقييم + تأمين + بطاقة الإقامة 964 ل.ت (لا إعفاء منها لأي جنسية) + رسوم الإقامة 2026 (الشهر الأول حد أقصى 3,359.90 ل.ت / إضافي 2,232.30 ل.ت/شهر) — لكن مواطني سوريا وفلسطين (وكذلك التشيك والدنمارك وإيرلندا وكوسوفو ونيبال وسريلانكا وتركمانستان وقبرص الشمالية) معفَون من رسم الإقامة بمبدأ المعاملة بالمثل ولا يدفعون سوى بدل البطاقة 964 ل.ت — + ترجمة/نوتر • للتفاصيل الكاملة: /article/residence-permit-fees-2026',
    description = 'إقامة تُمنح بناءً على ملكية عقار سكني ضمن شروط مالية وإجرائية محددة. انتبه لشرط جوهري تشترطه إدارة الهجرة صراحةً: يجب أن يكون العقار مسكناً وأن يستخدمه الأجنبي نفسه للسكن — ولا يجوز تأجيره أو استعماله لأي غرض مدرّ للدخل، وإلا سقط سبب منح الإقامة. قوة الملف تعتمد على: طابو صحيح + تقييم مطابق + عنوان ثابت + تأمين صحي + ملف مالي/قانوني نظيف.',
    steps = '["قبل الشراء: تحقق من أهلية العقار (أن يكون سكنياً/قيود/رهن/حجز) ومن أن قيمته وقت الشراء (تاريخ الاكتساب) تُحقق الحد المطلوب — إدارة الهجرة تشترط ألا تقلّ قيمة المسكن بتاريخ اكتسابه عن 200,000 دولار أمريكي بما يعادلها بالليرة، لا قيمته وقت تقديم الطلب.", "أصدر تقييم عقاري رسمي مطابق للشروط، واحتفظ بنسخة منه.", "أكمل نقل الملكية في الطابو واستخرج الطابو النهائي باسمك.", "ثبّت عنوان السكن في النفوس إذا كان العقار عنوان إقامتك الفعلي، واستخرج سند إقامة (Yerleşim Yeri Belgesi).", "اشترِ تأميناً صحياً مناسباً لفترة الإقامة المطلوبة.", "قدّم الطلب عبر e-ikamet واختر نوع الإقامة العقارية/قصيرة الأمد حسب ما يتيحه النظام في ولايتك."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'investor-residence';

UPDATE consultant_scenarios SET
    cost = 'ضريبة العقار (خارج البلديات الكبرى): مسكن 0.1% | بناء آخر 0.2% | أرض زراعية 0.1% | أرض بناء (arsa) 0.3% — وتتضاعف هذه النسب 100% داخل حدود البلديات الكبرى (Büyükşehir) ومناطقها المجاورة أي İstanbul وAntalya وİzmir وBursa وغيرها، فتصبح 0.2% و0.4% و0.2% و0.6% (المادتان 8 و18 من القانون 1319) | ضريبة الإيجار: 15-40% حسب الشريحة',
    last_update = '2026-07'
WHERE id = 'investor-tax-obligations';

UPDATE consultant_scenarios SET
    legal = 'إجراءات المحاكمة تركية دائماً، أما القانون الذي يُطبَّق على أسباب الطلاق والنفقة بين المطلَّقَين والحضانة فيحدده قانون MÖHUK رقم 5718: القاعدة هي القانون الوطني المشترك للزوجين (المادة 14) — لكن لها استثناءات تخص جمهور هذا الدليل مباشرة: اللاجئون وعديمو الجنسية يُطبَّق عليهم قانون محل إقامتهم، أي القانون التركي عملياً لمن يقيم في تركيا (المادة 4/1-أ)، وأي حكم في القانون الأجنبي يخالف النظام العام',
    steps = '["حدد نوع الطلاق: اتفاقي (Anlaşmalı) أو نزاعي/شقاق (Çekişmeli). الاتفاقي أسرع لكنه يحتاج اتفاق مكتوب على الحقوق.", "اجمع أدلة أساسية: الزواج، السكن، الأطفال، الدخل، وأي مراسلات مهمة (عند النزاع).", "استشر محامياً لتقدير أثر الطلاق على الإقامة/الأطفال، خصوصاً إذا كان أحد الطرفين يعتمد على الإقامة العائلية. واعلم أن القانون يفتح لك باباً: إذا كنت أجنبياً متزوجاً من مواطن تركي وأمضيت 3 سنوات على الأقل بإقامة عائلية، يجوز منحك إقامة قصيرة الأمد بعد الطلاق؛ وإذا ثبت بقرار محكمة أنك ضحية عنف أسري يسقط شرط الثلاث سنوات (المادة 34/6 من القانون 6458). النص يقول «يجوز أن تُمنح» ولا يجعلها تلقائية، لكنه أساس قانوني تتقدّم به إلى إدارة الهجرة.", "إذا كان اتفاقياً: جهّز بروتوكول اتفاق واضح (نفقة/حضانة/زيارة/تقسيم ممتلكات إن وجدت) ثم حدّد موعد المحكمة.", "بعد الحكم: تابع إجراءات تثبيت/ترجمة الحكم عند الحاجة (قنصلية/أبوستيل/ترجمة محلفة) حسب الدولة والجهة المطلوبة."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'legal-divorce';

UPDATE consultant_scenarios SET
    cost = 'الرسم مرتفع جداً ويتغيّر كل كانون الثاني: المبلغ المطبَّق اعتباراً من 1/1/2026 هو 54,258.00 ليرة (التعرفة رقم 8 من قانون الرسوم 492). يجب دفعه قبل إتمام التسجيل؛ والجهاز الذي يُسجَّل بدون دفع الرسم تُغلقه BTK ويُحصَّل الرسم بزيادة 50% مع فوائد التأخير. قارن هذا المبلغ بسعر شراء هاتف داخل تركيا قبل أن تقرر، وتحقق من الرقم المحدَّث على e-Devlet.',
    steps = '["تحقق أولاً من مهلتك ومن حقك في التسجيل: الهاتف المُحضَر من الخارج يعمل 120 يوماً فقط من تاريخ دخولك بدون تسجيل، وبعدها تقطعه هيئة BTK عن الشبكة. كما أن حق التسجيل محدود بجهاز واحد لكل شخص كل 3 سنوات — تحقق من حقك عبر خدمة «IMEI Kayıt Hakkı Sorgulama» على e-Devlet قبل أن تدفع أي شيء.", "استخرج/تحقق من رقم IMEI الصحيح (قد يكون هاتفين SIM).", "ادفع الرسوم/الضريبة بالطريقة الرسمية المعتمدة، واحتفظ بالإيصال.", "سجّل دخولك إلى e-Devlet واستخدم خدمة تسجيل IMEI لإدخال البيانات بشكل مطابق للجواز.", "تأكد أن شريحة الهاتف (SIM) باسم نفس الشخص صاحب الجواز/الإقامة، لأن عدم التطابق سبب رفض شائع.", "بعد التسجيل: أعد تشغيل الهاتف وانتظر التفعيل؛ إذا حصلت مشكلة راجع شركة الاتصالات أو الدعم الرسمي."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'phone-imei';

UPDATE consultant_scenarios SET
    description = 'تركيا تتجه لإنهاء نظام الحماية المؤقتة (الكملك) تدريجياً. اعتباراً من 1/1/2026 صارت تُؤخذ حصة مشاركة (katılım payı) في الخدمات الصحية من حاملي الحماية المؤقتة، مع بقاء تغطية تكلفة العلاج على الدولة لمن يثبت عدم قدرته على الدفع، وإمكانية استرداد حصة المشاركة عند الطلب، وسيُطلب من السوريين تحويل وضعهم لإقامة رسمية.',
    legal = 'لا يوجد قرار رسمي نهائي بإلغاء الحماية المؤقتة بعد، لكن التوجه واضح نحو الإنهاء التدريجي. لا يوجد قرار رسمي نهائي بإلغاء الحماية المؤقتة بعد، لكن التوجه واضح نحو الإنهاء التدريجي. العدد المعلن رسمياً على موقع إدارة الهجرة في 9/7/2026: نحو 2 مليون و245 ألف سوري في تركيا.',
    steps = '["تابع باستمرار قرارات إدارة الهجرة التركية عبر الموقع الرسمي أو E-Devlet.", "ابدأ بتجهيز أوراقك لتحويل وضعك إلى إقامة رسمية (عمل أو عائلية أو غيرها) إذا كنت مؤهلاً — مع الانتباه إلى أن حصولك على أي حق إقامة قانوني آخر يُنهي حمايتك المؤقتة فردياً (المادة 12/1(د) من لائحة الحماية المؤقتة)، وإذا انتهت الإقامة لاحقاً فلا تعود تلقائياً إلى الكملك بل تُقرَّر حالتك فردياً من المديرية العامة (المادة 13). كما أن سنوات الكملك لا تُحتسب ضمن مدد الإقامة ولا تمنح انتقالاً للإقامة الدائمة (المادة 25).", "منذ 1/1/2026 تُؤخذ «حصة مشاركة» (katılım payı) من حاملي الحماية المؤقتة عند تلقّي الخدمة الصحية وفق تعرفة SGK — المادة 27/1(ب) من لائحة الحماية المؤقتة. من ثبت — عبر وزارة الأسرة بالتنسيق مع إدارة الهجرة — عدم قدرته على الدفع: تكلفة علاجه تبقى على الدولة (تُدفع من صندوق دعم التضامن الاجتماعي — المادة 27/1(ج))، ويمكنه استرداد حصص المشاركة التي دفعها بطلب من وقفية التضامن الاجتماعي (SYDV) — المادة 2", "راجع محامياً أو منظمة حقوقية لمعرفة خياراتك القانونية المتاحة."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'protection-status-2026';

UPDATE consultant_scenarios SET
    cost = 'للشهادة الجامعية: رسم تقديم رسمي لدى YÖK قدره 1,250 ليرة لعام 2026 (ونفس المبلغ لطلب إعادة الدراسة، و300 ليرة لأي طلب معلومات/وثيقة)، يُدفع مسبقاً إلى حساب YÖK في زراعات بنك — إضافة إلى الترجمة والنوتر والتصديق ومصاريف المراجعات. أما معادلة الشهادة المدرسية لدى MEB فلا رسم مقرر عليها في اللائحة.',
    docs = '["الشهادة الأصلية + كشف علامات.", "تصديق الشهادة الأصلية: أبوستيل، وإن لم يكن بلد الإصدار طرفاً في اتفاقية الأبوستيل (كسوريا) فتصديق من وزارة التربية أو وزارة الخارجية أو السفارة — إلزامي للمتخرجين. + ترجمة تركية مصدّقة من كاتب عدل تركي (نوتر) أو من قنصلية تركية — التصديق إلزامي وليس اختيارياً.", "هوية/كملك/إقامة أو جواز.", "بيان عنوان/سند إقامة (قد يُطلب).", "أي وثائق داعمة (منهاج/ساعات/تصديق) حسب نوع الشهادة."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'student-denklik';

UPDATE consultant_scenarios SET
    steps = '["السكن الحكومي (KYK): تقدّم عبر e-Devlet بعد التسجيل في الجامعة", "موعد التقديم عادةً في أغسطس-سبتمبر", "السكن الخاص (Özel Yurt): تواصل مباشرة مع المبنى وقدّم الأوراق", "بعد القبول، سجّل عنوان السكن في النفوس", "التقديم على مهاجع الدولة يتم عبر e-Devlet حصراً، ولا يمكن للطالب الأجنبي التقديم إلا إذا كان يملك «رقم الأجنبي» (Yabancı Kimlik Numarası) من مديرية الهجرة — استخرجه قبل فتح باب التقديم. المطلوب: وثيقة الطالب (Öğrenci Belgesi) + وثيقة الإقامة + نسخة مصدّقة من جواز السفر."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'student-dormitory';

UPDATE consultant_scenarios SET
    cost = 'قسط GSS للطالب الأجنبي محدّد بالقانون: ثلث الحد الأدنى للأجر الإجمالي × 12٪. لعام 2026 = 33,030 ÷ 3 = 11,010 × 12٪ ≈ 1,321 ليرة شهرياً (يتغيّر كل كانون الثاني مع الحد الأدنى للأجر). أما التأمين الخاص فسعره يختلف حسب الشركة والعمر — راجع عرض السعر مباشرة.',
    steps = '["طلاب المنح (Bursları): التأمين مشمول — لا حاجة لإجراء إضافي", "الطلاب الآخرون: اشتر تأميناً صحياً خاصاً (مطلوب لتجديد الإقامة)", "لا يوجد شرط «سنة إقامة» للطالب: القانون 5510 (المادة 60) يستثني الطالب الأجنبي صراحةً من شرط السنة، ويمنحه مهلة ثلاثة أشهر من تاريخ بدء العام الدراسي لتقديم طلب GSS عبر e-Devlet (خدمة «Yabancı Uyruklu Öğrencilerin GSS Başvurusu ve Takibi»). لا تؤجّل: خارج هذه المهلة تبقى بلا تغطية حكومية حتى النافذة التالية. وبعد تعديل كانون الثاني 2025 (القانون 7538)، من فاتته المهلة لا يُحرم نهائياً — يمكنه التقديم خلال الأشهر الثلاثة الأولى من بداية أي عام دراسي لاحق ما دام قيده الدراسي مستمراً.", "قدّم طلب GSS في مكتب SGK مع وثيقة الطالب", "بعد التسجيل، احجز مواعيدك عبر MHRS"]'::jsonb,
    last_update = '2026-07'
WHERE id = 'student-health-insurance-options';

UPDATE consultant_scenarios SET
    docs = '["هوية/كملك أو إقامة.", "الشهادة الأصلية.", "كشف علامات مصدّق.", "ترجمة تركية مصدّقة من نوتر تركي أو من قنصلية تركية (إلزامية) + تصديق الشهادة الأصلية بالأبوستيل، أو — إن كان بلد الإصدار غير طرف في اتفاقية الأبوستيل كسوريا — تصديق وزارة التربية أو وزارة الخارجية أو السفارة.", "بيان إقامة."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'student-highschool-denklik';

UPDATE consultant_scenarios SET
    description = 'الثانوية المفتوحة خيار للدراسة عن بعد ضمن النظام التركي، وتحتاج تسلسلاً دراسياً صحيحاً ومعادلة (Denklik) في كثير من الحالات. تحذير مهم قبل التسجيل: الثانوية المفتوحة مؤسسة ثانوية تركية تابعة لوزارة التربية، ومن يدرس أو يتخرّج منها كأجنبي تسري عليه قاعدة YÖK التي تمنع الأجانب الذين درسوا في ثانوية داخل تركيا من التقديم على كوتا «الطلاب الأجانب» (TR-YÖS) — ويصبح مساره امتحان YKS. إن كنت تخطّط لدخول الجامعة عبر كوتا الطلاب الأجانب فاستشر قبل التسجيل.',
    last_update = '2026-07'
WHERE id = 'student-open-highschool';

UPDATE consultant_scenarios SET
    docs = '["وثيقة طالب حديثة (Öğrenci Belgesi).", "قبول/تسجيل من المؤسسة التعليمية (إن توفر).", "جواز سفر/هوية + صور بيومترية — ويجب أن تبقى صلاحية الجواز أطول بـ 60 يوماً على الأقل من مدة الإقامة المطلوبة (المادة 21/2 من القانون 6458)، وإلا تُمنح الإقامة أقصر أو يُرفض الطلب.", "تأمين صحي.", "سند إقامة/قيد نفوس + عنوان صحيح.", "إيصالات الرسوم/الضرائب عند الحاجة."]'::jsonb,
    steps = '["أكمل التسجيل النهائي في الجامعة/المعهد/تومر بشكل رسمي واحصل على وثيقة طالب حديثة (Öğrenci Belgesi).", "تأكد من نوع البرنامج ومدته لأن بعض المؤسسات/الدورات لا تمنح حق إقامة طالب.", "ثبّت عنوان السكن (نفوس) واستخرج سند إقامة/قيد نفوس من e-Devlet إذا طُلب.", "اشترِ تأميناً صحياً مناسباً لفترة الإقامة (وتأكد من صحة الاسم/الرقم).", "قدّم الطلب عبر e-ikamet: طلاب الجامعة/المعهد العالي يختارون «Öğrenci / Student Residence»، أما المسجّلون في دورة لغة تركية (تومر) فيختارون الإقامة قصيرة الأمد بسبب «Türkçe öğrenme kurslarına katılacaklar» (وتُمنح مرتين كحد أقصى).", "جهّز الملف الورقي مرتباً وسلمه حسب نظام ولايتك (موعد/بريد/تسليم).", "تابع الطلب والرسائل. إذا طلبوا نقص، سلّمه بسرعة ضمن المهلة."]'::jsonb,
    tip = 'العمل أثناء الدراسة منظَّم بالقانون لا بتعليمات الجامعة: المادة 41 من القانون 6458 تشترط الحصول على إذن عمل (çalışma izni)، وطلاب الليسانس والدبلوم لا يبدأ حقهم بالعمل إلا بعد السنة الأولى. العمل دون إذن يعرّضك لغرامة ولإلغاء إقامة الطالب لاستعمالها خارج غرضها (المادة 40/1-ج). احتفظ بسجل حضور/قيد لإثبات أنك «طالب فعلي».',
    title = 'إقامة الطالب (جامعة) — وطلاب دورات اللغة التركية (تومر) يحصلون على إقامة قصيرة الأمد لا على إقامة طالب',
    last_update = '2026-07'
WHERE id = 'student-residence';

UPDATE consultant_scenarios SET
    description = 'TR-YÖS هو الامتحان الموحد الذي تعتمده الجامعات لقبول الطلاب الأجانب. تنبيه قبل أن تدفع الرسوم: قواعد YÖK لقبول الطلاب من الخارج تستبعد الأجنبي الذي درس أو تخرّج من ثانوية داخل تركيا من كوتا «الطلاب الأجانب» (باستثناء مدارس السفارات والمدارس الدولية ضمن MOBİS ومشاريع MEB/YÖK) — هؤلاء مسارهم امتحان YKS. كما أن نتيجة TR-YÖS صالحة سنتين فقط. النجاح لا يكفي وحده؛ يجب فهم التقويم: تسجيل → امتحان → نتائج → مفاضلات الجامعات → تثبيت القبول.',
    last_update = '2026-07'
WHERE id = 'student-yos';

UPDATE consultant_scenarios SET
    description = 'بعد التغييرات السياسية في سوريا (ديسمبر 2024)، بدأت موجة عودة كبيرة. وفق ما أعلنته إدارة الهجرة في 9/7/2026: نحو 710 آلاف سوري عادوا طوعاً منذ 8 كانون الأول/ديسمبر 2024، ونحو 1.5 مليون منذ 2016، مع مخاوف حقوقية من عمليات إعادة قسرية.',
    last_update = '2026-07'
WHERE id = 'syria-mass-return-2025';

UPDATE consultant_scenarios SET
    steps = '["تنبيه: برنامج «الذهاب والعودة» الرسمي كان محدوداً بالفترة 1/1/2025 – 1/7/2025 (إعلان وزير الداخلية 27/12/2024)، ولم تنشر إدارة الهجرة أي تمديد له حتى تاريخه. وفي الأسئلة الشائعة الرسمية لإدارة الهجرة: الخروج إلى خارج البلاد — باستثناء من خرج بإذن رسمي صادر عن إدارة الهجرة — يؤدي إلى إلغاء بطاقة الحماية المؤقتة. لا تسافر إلى سوريا إلا بوثيقة إذن رسمية سارية، وتحقق أولاً من وجود إعلان رسمي جديد على", "الحصول على وثيقة سفر مؤقتة تحدد المعبر الحدودي وتاريخ الذهاب والعودة.", "الخروج والعودة من المعبر المذكور في وثيقتك فقط. في الإعلان الرسمي للبرنامج (27/12/2024) كان المعبران المحدَّدان هما جوبان بيه/كليس (Çobanbey) وغصن الزيتون/هطاي (Zeytindalı). لا تعتمد على أسماء معابر متداولة — اقرأ اسم المعبر المكتوب في وثيقة إذن الطريق.", "الالتزام بالمدة المحددة — التأخير يعرّض الكملك للإلغاء."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'syria-visit-official';

UPDATE consultant_scenarios SET
    legal = 'تعليم أطفال الحماية المؤقتة يُدار تحت مسؤولية وزارة التربية الوطنية — المادة 28 من لائحة الحماية المؤقتة، والتعليم من الخدمتين الوحيدتين اللتين لا يجوز تقييدهما حتى عند الإخلال بالالتزامات — المادة 35/2. وتسجيل الطفل في نظام e-Okul يتم استناداً إلى رقم الهوية الصادر عن وزارة الداخلية، لذلك الخطوة الحاسمة هي إتمام التسجيل لدى مديرية الهجرة في ولايتك للحصول على رقم الأجنبي (99...)، لا التفاوض مع كل مدرسة على حدة.',
    last_update = '2026-07'
WHERE id = 'syrian-child-school-no-kimlik';

UPDATE consultant_scenarios SET
    description = 'ترشيح السوريين للجنسية الاستثنائية بفضل مؤهلاتهم (أصحاب تصاريح العمل الطويلة، شهادات جامعية، أساتذة، أطباء). تنبيه أساسي: بطاقة الحماية المؤقتة (الكملك) بحد ذاتها لا تمنح صاحبها حق التقدّم للجنسية التركية، ولا تُحتسب مدتها ضمن مدد الإقامة، ولا تمنح انتقالاً للإقامة الدائمة — المادة 25 من لائحة الحماية المؤقتة. أي شخص يعرض عليك «تقديم ملف جنسية» بالكملك وحده فهو يبيعك وهماً.',
    legal = 'الجنسية الاستثنائية تُمنح بقرار من رئاسة الجمهورية وفق المادة 12 من قانون الجنسية 5901. المسار المقصود في هذه البطاقة هو الفقرة (أ): من تقدّم الوزارات المعنية اقتراحاً مسبباً بشأنهم — وهذا لا يُقدَّم عليه بطلب فردي. لكن المادة نفسها تنصّ في الفقرة (ب) على مسار آخر لا يحتاج ترشيحاً: من حصل على إقامة وفق المادة 31/1(ي) من القانون 6458 (مسار الاستثمار) وحملة البطاقة الفيروزية، مع الزوج/الزوجة والأولاد القاصرين أو المعالين.',
    last_update = '2026-07'
WHERE id = 'syrian-citizenship';

UPDATE consultant_scenarios SET
    cost = 'المعادلة المدرسية عبر مديرية التربية: لا رسم على وثيقة المعادلة نفسها. المعادلة الجامعية عبر YÖK: رسم طلب المعادلة 1.250 ليرة لسنة 2026 (قرار مجلس التعليم العالي 24/12/2025، ساري 1/1/2026–31/12/2026) يُدفع مسبقاً ويُقدَّم إيصاله يوم الموعد. يُضاف إلى ذلك تكلفة الترجمة المحلفة والنوتر حسب عدد الصفحات.',
    last_update = '2026-07'
WHERE id = 'syrian-denklik';

UPDATE consultant_scenarios SET
    legal = 'تغيير العنوان يجب تبليغه خلال عشرين يوم عمل — المادة 33/2(د) من لائحة الحماية المؤقتة والمادة 50/3 من قانون خدمات النفوس 5490. من لا يلتزم يُنذَر أولاً، ثم يمكن تقييد استفادته من الحقوق كلياً أو جزئياً، «باستثناء خدمات التعليم والصحة الطارئة» التي لا يجوز تقييدها — المادة 35/2. أما إلغاء الحماية المؤقتة فيصدر عن الولاية لمن لم يفِ بواجب التبليغ ثلاث مرات متتالية دون عذر — المادة 12/3. والإدلاء ببيان عنوان غير صحيح جريمة عقوبتها الحبس من ستة أشهر إلى أربع سنوات — المادة 67/1 من القانون 5490.',
    last_update = '2026-07'
WHERE id = 'syrian-fix-address';

UPDATE consultant_scenarios SET
    steps = '["تحقق من الحي قبل الاستئجار: اسأل المختار (Muhtar) إذا كان الحي مفتوحاً للتسجيل", "القوائم تتغير، لكن إدارة الهجرة تنشر قائمة الأحياء المغلقة رسمياً مرفقةً بإعلان «Mahalle Kapatma Duyurusu» على goc.gov.tr وعلى مواقع مديريات الهجرة في الولايات (1.169 حيّاً اعتباراً من 1/7/2022) — تحقّق من القائمة المنشورة قبل توقيع أي عقد، ولا تكتفِ بكلام شفهي.", "إذا رُفض تسجيلك في النفوس، اسأل عن السبب كتابياً", "يمكنك الانتقال لحي آخر مفتوح في نفس المدينة", "الاستثناءان المنصوص عليهما في إعلان إدارة الهجرة هما فقط: تسجيل المولود الجديد، ولمّ شمل الأسرة النواة (الزوج/الزوجة والأولاد القاصرون). لا يوجد استثناء منشور بسبب العمل، ولا مسار معلن لاستثناء يمنحه الوالي."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'syrian-housing-banned-zones';

UPDATE consultant_scenarios SET
    legal = 'مغادرتك تركيا بإرادتك تُنهي حمايتك المؤقتة فردياً — المادة 12/1(أ) من لائحة الحماية المؤقتة. ولا يوجد في النص أي «حظر 5 سنوات»: إن عدتَ لاحقاً إلى الحدود طالباً الحماية المؤقتة، فالمديرية العامة هي التي تقرّر حالةً بحالة إن كانت أحكام الحماية المؤقتة ستُطبَّق عليك — المادة 13. أي لا ضمانة بالعودة ولا مدة معلومة تنتظرها.',
    last_update = '2026-07'
WHERE id = 'syrian-leaving-turkey';

UPDATE consultant_scenarios SET
    steps = '["التوجّه إلى أقرب مركز شرطة لتنظيم ضبط فقدان/سرقة (Kayıp/Çalıntı Tutanağı). ملاحظة: رقم 155 لم يعد رقماً مستقلاً — جميع أرقام الطوارئ في تركيا موحّدة تحت الرقم 112.", "الذهاب إلى أقرب مخفر شرطة لعمل ضبط فقدان (Kayıp Tutanağı).", "حجز موعد تحديث بيانات عبر موقع إدارة الهجرة.", "الذهاب في الموعد المرجو إلى إدارة الهجرة مع ضبط الشرطة والمستندات الداعمة."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'syrian-lost-id';

UPDATE consultant_scenarios SET
    cost = 'دفتر العائلة (Aile Cüzdanı) سعره محدَّد وطنياً وليس حسب البلدية: 1.202,00 ليرة لسنة 2026 (تعميم الأوراق ذات القيمة رقم 97 الصادر عن وزارة الخزانة والمالية). أما رسم عقد القران نفسه (nikâh ücreti) فتحدّده كل بلدية على حدة ويختلف حسب القاعة والتوقيت — اطلب التعرفة مكتوبة من بلديتك. يُضاف ما قد يُطلب من ترجمة محلفة/تصديق نوتر حسب حالتك.',
    steps = '["استخراج «ورقة العزوبية/أهلية الزواج» (Evlenme Ehliyet Belgesi): تُطلب إلكترونياً عبر e-Devlet من خدمة إدارة الهجرة (goc-idaresi-evlenme-ehliyet-belgesi-basvurusu) لحاملي الحماية المؤقتة والحماية الدولية منذ 1/7/2021 — لا داعي لحجز موعد «تحديث بيانات» لهذا الغرض.", "إجراء الفحص الطبي (Thalassemia) في المستوصف.", "حجز موعد في البلدية وعقد القران.", "استلام دفتر العائلة الأحمر (Aile Cüzdanı).", "تحديث الكملك/البيانات بعد الزواج (إضافة الحالة الاجتماعية وربط الزوج/الزوجة)."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'syrian-marriage';

UPDATE consultant_scenarios SET
    description = 'حدّد وضعك بدقة قبل التفكير في أي دعوى. إذا كان لديك عقد زواج صادر في سوريا فالزواج صحيح شكلاً في تركيا، لأن شكل الزواج يخضع لقانون البلد الذي أُبرم فيه (المادة 13/2 من القانون 5718)، والمطلوب غالباً هو تحديث الحالة المدنية في ملفك لدى إدارة الهجرة بالوثيقة مترجمة ومصدّقة، دون دعوى ودون أتعاب محاماة (المادة 21/4 من لائحة الحماية المؤقتة)، ويجب الإبلاغ خلال 20 يوم عمل من تغيّر الحالة المدنية (المادة 33/2-د). أما إذا كان الزواج «شرعياً/أمام شيخ» داخل تركيا فقط، فليس له أثر مدني ولا توجد دعوى تجعله زواجاً رسمياً بأثر رجعي؛ المسار هو عقد زواج رسمي أمام مأمور الزواج، ومعالجة نسب الأطفال بمسار منفصل. استشر محامياً بعد أن تحدّد أي الحالتين تنطبق عليك.',
    last_update = '2026-07'
WHERE id = 'syrian-marriage-not-registered';

UPDATE consultant_scenarios SET
    description = 'عملية نقل قيود الحماية المؤقتة من ولاية إلى أخرى. النقل ليس حقاً تلقائياً: مديرية الهجرة تشترط وجود «سبب معقول» مثل العمل أو التعليم أو الصحة أو صلة القرابة — والقائمة ذُكرت على سبيل المثال لا الحصر — والقرار تقديري للإدارة وقد يُرفض.',
    last_update = '2026-07'
WHERE id = 'syrian-move-kimlik';

UPDATE consultant_scenarios SET
    description = 'تسجيل المولود يبدأ من المشفى ثم النفوس ثم الهجرة. ولا تؤجّل: المهلة القانونية لتبليغ النفوس 30 يوماً من الولادة، ولإبلاغ إدارة الهجرة 20 يوم عمل. التأخير يعطّل معاملات لاحقة (لقاحات، مدرسة، سفر)، وعدم الإبلاغ في المهلة قد يفتح إجراءات إدارية بحق ملفك ويُحتسب ضمن مخالفات واجب الإبلاغ.',
    steps = '["الحصول على شهادة ولادة (Doğum Raporu) من المشفى.", "تسجيل الولادة في دائرة النفوس (Nüfus) والحصول على شهادة الميلاد — والمهلة القانونية 30 يوماً من تاريخ الولادة لتبليغ النفوس (المادة 15 من قانون خدمات النفوس رقم 5490)، ثم يجب إبلاغ إدارة الهجرة بالولادة خلال 20 يوم عمل (المادة 33/2-د من لائحة الحماية المؤقتة).", "حجز موعد تحديث بيانات في الهجرة (سبب: إضافة مولود).", "اصطحاب الطفل + الأبوين + الشهادات الأصلية في موعد الهجرة.", "بعد إصدار الكملك: تأكد من الاسم/التهجئة بالتركية/اللاتينية واحفظ نسخة صورة واضحة."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'syrian-newborn';

UPDATE consultant_scenarios SET
    steps = '["احصل على العنوان التفصيلي (المنطقة/الحي) من صاحب المنزل أو المكتب العقاري.", "استخدم أداة \"فاحص المناطق\" في الموقع أو اتصل بالرقم 157 للتأكد إن كان الحي مغلقاً للأجانب.", "إذا كان مغلقاً: لا تستأجر مهما كانت المغريات. الاستثناءان المعلَنان رسمياً من إغلاق الأحياء هما اثنان فقط: المواليد الجدد، ولمّ شمل «الأسرة النواة» (الزوج/الزوجة والأولاد) المسجّلة أصلاً في ذلك العنوان.", "ثبّت العنوان في النفوس فور توقيع العقد ولا تؤجل ذلك أي يوم."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'syrian-prohibited-check';

UPDATE consultant_scenarios SET
    description = 'لا يستطيع المواطن السوري تملّك عقار في تركيا باسمه الشخصي. فالسوريون غير مدرجين ضمن الجنسيات المسموح لها بالتملّك بموجب القرار الصادر استناداً إلى المادة 35 من قانون الطابو رقم 2644، والقيد مُدمج في نظام الطابو (TAKBİS)، ولذلك لا يمكنهم أيضاً التقدّم للجنسية التركية عن طريق شراء عقار. المسار الوحيد المتاح عملياً هو التملّك باسم شركة مؤسَّسة في تركيا، وله تكاليف والتزامات ضريبية ومحاسبية مستمرة. لا تدفع عربوناً ولا توقّع وعد بيع قبل التحقق من وضعك لدى مديرية الطابو (TKGM) واستشارة محامٍ.',
    last_update = '2026-07'
WHERE id = 'syrian-property-ownership';

UPDATE consultant_scenarios SET
    cost = 'إن كنت غير قادر على دفع أتعاب المحاماة فلك الحق في طلب «المساعدة القضائية» (Adli Yardım) مجاناً من نقابة المحامين في ولايتك؛ المادة 53 من لائحة الحماية المؤقتة تحفظ صراحةً أحكام المساعدة القضائية في قانون المحاماة رقم 1136، والمادة 176 منه تعرّفها بأنها تقديم خدمات المحاماة لمن لا يملك تحمّل الأتعاب ومصاريف التقاضي. أما إذا وكّلت محامياً على حسابك فاعلم أن الحد الأدنى الملزم لأتعاب دعوى أمام المحكمة الإدارية لسنة 2026 هو 30,000 ليرة (بدون جلسة) و40,000 ليرة (مع جلسة) بحسب تعرفة الأتعاب المنشورة في الجريدة الرسمية، ولا يجوز الاتفاق على أقل منها.',
    legal = 'المهلة تتوقف على نوع القرار المُبلَّغ إليك، فاقرأ ورقة التبليغ فوراً: إذا كان المُبلَّغ قرار ترحيل (sınır dışı etme kararı) فالمهلة 7 أيام فقط من تاريخ التبليغ للطعن أمام المحكمة الإدارية (المادة 53/3 من القانون 6458 بصيغتها المعدّلة سنة 2024)، وخلال مدة الطعن وحتى انتهاء المحاكمة لا يجوز ترحيلك. أما إذا كان المُبلَّغ قراراً إدارياً آخر (وضع كود/قيد فقط) فالمهلة العامة 60 يوماً (المادة 7 من القانون 2577).',
    last_update = '2026-07'
WHERE id = 'syrian-return-code';

UPDATE consultant_scenarios SET
    steps = '["يُعتبر هذا الإجراء غير قانوني إطلاقاً ويصنف تهريباً.", "عند اكتشاف النظام الحدودي التركي أو الشرطة للأمر، سيتم إبطال الكملك فوراً.", "ستُتخذ بحقك إجراءات قد تشمل منع الدخول إلى تركيا أو الترحيل. منع الدخول ينظّمه القانون 6458 في المادة 9، ومدته 5 سنوات كحد أقصى وقد تُمدَّد حتى 10 سنوات إضافية عند وجود تهديد جدّي للنظام العام أو الأمن العام، ويجوز لمديرية الهجرة العامة رفعه لاحقاً. لا تعتمد على «رموز» متداولة بين الناس لتفسير وضعك؛ فلا توجد قائمة رسمية منشورة بهذه الرموز. اطلب من إدارة الهجرة تبليغاً مكتوباً بالقرار وسببه.", "لا تُقدِم على «العودة الطوعية» كحل لهذه المشكلة. توقيع استمارة العودة الطوعية يُنهي حمايتك المؤقتة نهائياً بحسب مديرية الهجرة، وإذا عدت لاحقاً إلى تركيا فإن إعادة شمولك بالحماية المؤقتة قرار تقديري تتخذه مديرية الهجرة فردياً وليس حقاً لك (المادة 13 من لائحة الحماية المؤقتة). راجع مديرية الهجرة في ولايتك واسأل عن المسارات النظامية المتاحة حالياً (وقد سبق أن طبّقت وزارة الداخلية نظام خروج ودخول بموافقة مسبقة عبر معبري كلّس چوبان بك وهاتاي غصن الزيتون) قبل أي خطوة لا رجعة فيها."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'syrian-syria-visit-risk';

UPDATE consultant_scenarios SET
    cost = 'إذن السفر نفسه مجاني. لكن انتبه: بموجب تعديل 28/11/2025 على لائحة الحماية المؤقتة صار يُؤخذ من المشمولين بالحماية المؤقتة «حصة مساهمة» (katılım payı) عن الخدمات الصحية وفق تبليغ التطبيقات الصحية للضمان الاجتماعي، وتُعاد هذه المبالغ عند الطلب لمن يثبت عدم قدرته على الدفع عبر صناديق التضامن والتكافل الاجتماعي.',
    legal = 'لائحة الحماية المؤقتة تُلزمك بالإقامة في الولاية المحدَّدة لك (المادة 33/2-أ) ولا تنص على أي استثناء «طوارئ» يعفيك من إذن السفر إلى ولاية أخرى. الحالات الإسعافية تُدار عبر النظام الصحي والإحالة الرسمية (Sevk)؛ لا تسافر إلى ولاية أخرى اعتماداً على استثناء طارئ غير موجود في النص، بل اطلب الإحالة وإذن السفر معاً.',
    last_update = '2026-07'
WHERE id = 'syrian-travel-medical';

UPDATE consultant_scenarios SET
    legal = 'منح إذن السفر قرار تقديري للإدارة، لكنه ليس بلا تسبيب ولا بلا رقابة قضائية: المادة 7 من القانون 3071 تُلزم الجهة المختصة بالرد على طلبك «بشكل مسبَّب» خلال ثلاثين يوماً كحد أقصى، والمادة 125 من الدستور تنص على أن «كل أعمال وتصرفات الإدارة قابلة للطعن أمام القضاء». إذا رُفض طلبك فاطلب الرد المكتوب المسبَّب، فهو الوثيقة التي تحتاجها لأي اعتراض لاحق.',
    tip = 'قدّم الطلب قبل موعد سفرك بوقت كافٍ، ولا تحجز تذكرة ولا تتحرّك قبل صدور الموافقة عبر رسالة SMS واستخراج الوثيقة من e-Devlet؛ لا توجد مدة معالجة رسمية معلنة لطلب إذن السفر.',
    last_update = '2026-07'
WHERE id = 'syrian-travel-visit';

UPDATE consultant_scenarios SET
    description = 'تحديث بيانات الكملك إجراء ضروري عند تغيير العنوان، الزواج، الطلاق، أو الولادة. ويتم حصراً عبر حجز موعد في إدارة الهجرة. إهمال التحديث ليس مجرد «تجميد» للكملك: من يهمل واجب الإبلاغ ثلاث مرات متتالية بدون عذر تُلغى حمايته المؤقتة بقرار من الولاية (المادة 12/3 من لائحة الحماية المؤقتة)، وقبل ذلك يمكن تقييد استفادته من الخدمات كلياً أو جزئياً باستثناء التعليم والصحة الطارئة (المادة 35/2).',
    tip = 'لا تذهب بدون موعد إلا للحالات الحرجة جداً. والمهل القانونية بحسب المادة 33/2 من لائحة الحماية المؤقتة هي: 20 يوم عمل لتبليغ تغيير العنوان أو الحالة المدنية أو الولادة والوفاة، و30 يوماً لتبليغ تغيّر وضعك الوظيفي، و30 يوماً لتبليغ دخلك وأملاكك العقارية.',
    last_update = '2026-07'
WHERE id = 'syrian-update-data';

UPDATE consultant_scenarios SET
    cost = 'رسوم إذن العمل لعام 2026: 12,574.90 ليرة رسم إذن العمل (أو وثيقة الإعفاء) لمدة سنة واحدة، إضافةً إلى 964.00 ليرة بدل الورقة الثمينة — بحسب تعرفة قانون الرسوم المنشورة في الجريدة الرسمية بتاريخ 31/12/2025 عدد 33124 (مكرر 5). يدفعها صاحب العمل عادةً. تُحدَّث هذه المبالغ كل شهر كانون الثاني/يناير، فتحقّق من موقع وزارة العمل قبل الدفع.',
    steps = '["يجب أن يكون مضى 6 أشهر على تسجيلك في الحماية المؤقتة", "صاحب العمل يقدّم الطلب عبر نظام e-İzin (calismaizni.gov.tr) التابع لوزارة العمل — وانتبه لشرطين تُرفض الطلبات بسببهما غالباً: عدد العاملين المشمولين بالحماية المؤقتة في المنشأة لا يجوز أن يتجاوز 10% من عدد العاملين الأتراك فيها، وفي المنشآت التي يقل عدد عامليها عن عشرة يُسمح بعامل واحد فقط، ولا يجوز دفع أجر أقل من الحد الأدنى للأجور (المواد 8 و10 من لائحة أذون عمل المشمولين بالحماية المؤقتة 2016/8375). ومن يحق له «إذن عمل مستقل» يقدّم الطلب باسمه هو وليس عبر صاحب عمل (المادة 5/3).", "إذن العمل مرتبط بصاحب العمل وبالولاية المسجل فيها", "لا يمكن العمل في ولاية مختلفة عن الكملك بدون نقل", "بعد الموافقة لا يتم تسجيلك في الضمان الاجتماعي تلقائياً: صاحب العمل ملزم بتقديم إشعار بدء العمل (sigortalı işe giriş bildirgesi) إلى مؤسسة الضمان الاجتماعي خلال 30 يوماً من تبليغه بوثيقة إذن العمل. تحقّق بنفسك بعد أسابيع قليلة من تسجيلك عبر e-Devlet (كشف خدمة 4A) ولا تكتفِ بكلام صاحب العمل."]'::jsonb,
    tip = 'العمل بدون إذن رسمي يعرّضك ويعرّض صاحب العمل لغرامات كبيرة. أما أعمال الزراعة الموسمية وتربية الحيوانات فليست «إذن عمل رخيصاً» بل «إعفاء من إذن العمل» يُقدَّم طلبه إلى الولاية (الوالي) وليس إلى الوزارة، وقد تضع الوزارة حصصاً وقيوداً حسب الولاية (المادتان 5/4 و5/5 من اللائحة 2016/8375). ولا تفترض أنه مجاني: وثيقة الإعفاء خاضعة لنفس رسم إذن العمل بحسب تعرفة قانون الرسوم، ويُستثنى من الرسم فقط الإعفا',
    last_update = '2026-07'
WHERE id = 'syrian-work-permit-kimlik';

UPDATE consultant_scenarios SET
    legal = 'أنظمة MASAK (Mali Suçları Araştırma Kurulu - هيئة التحقيق في الجرائم المالية): البنوك مُلزمة بالتحقق من هوية العميل ومصدر أمواله. عتبات MASAK ليست عتبات «تبليغ تلقائي» بل عتبات تحقّق من الهوية: يلتزم البنك بالتحقق من هويتك وتحديد المستفيد الحقيقي إذا بلغ مبلغ العملية (أو مجموع عمليات مترابطة) 185,000 ل.ت فأكثر، وفي الحوالات الإلكترونية 15,000 ل.ت فأكثر (المادة 5 من لائحة التدابير). أما بلاغ العملية المشبوهة فلا عتبة له إطلاقاً ويشمل أي مبلغ. الحسابات غير المستخدمة لمدة طويلة قد تُجمَّد تلقائياً. يحق للبنك رفض فتح الحساب بدون إبداء أسباب.',
    last_update = '2026-07'
WHERE id = 'tourist-bank-open';

UPDATE consultant_scenarios SET
    legal = 'تحذير خطير: التنازل عن الكملك لا رجعة فيه. إذا رُفضت إقامتك بعد التنازل، ستصبح بلا وضع قانوني وقد تتعرض للترحيل. لا يوجد ضمان تلقائي بقبول الإقامة. المادة 12/1-د من لائحة الحماية المؤقتة (تنتهي الحماية المؤقتة فردياً بمجرد اكتساب حق إقامة قانوني آخر بموجب القانون)، والمادة 25 منها (بطاقة الحماية المؤقتة تمنح حق البقاء لكنها لا تعادل الإقامة، ولا تُحتسب ضمن مدد الإقامة، ولا تفتح باب الإقامة طويلة المدة ولا الجنسية).',
    last_update = '2026-07'
WHERE id = 'tourist-convert-kimlik';

UPDATE consultant_scenarios SET
    legal = 'المادة 24/2 من قانون 6458: تُقدَّم طلبات التمديد ابتداءً من تبقّي 60 يوماً على انتهاء الإقامة وقبل انتهائها في كل الأحوال. التقديم بعد الانتهاء: تُقبل الطلبات ممن تجاوز مدة إقامته أو فيزته حتى 10 أيام (المادة 21/2 من اللائحة التنفيذية)، وتُحتسب رسوم المدة المتجاوَزة. أما تجاوز أكثر من 10 أيام فيُعامل كمخالفة مع احتمال الرفض. لا يوجد سقف زمني إجمالي للإقامة قصيرة المدة؛ تُمنح وتُجدَّد بمدد تصل إلى سنتين في كل مرة (المادة 31/2). ومن أكمل 8 سنوات إقامة متصلة يحق له التقدّم لإقامة طويلة المدة (دائمة) وفق المادتين 42 و43 — وهذا حق اختياري وليس إلزاماً. • تنبيه: الإقامة قصيرة المدة تُلغى ولا تُجدَّد إذا بقيتَ خارج تركيا أكثر من 120 يوماً إجمالاً خلال آخر سنة (يُستثنى السفر لأسباب الخدمة العامة الإلزامية أو مهمة رسمية أو دراسة أو علاج) — المادة 29/1-ج من اللائحة التنفيذية.',
    steps = '["قدّم طلب التجديد عبر بوابة e-ikamet خلال آخر 60 يوماً من إقامتك الحالية: باب التقديم يُفتح عندما يتبقى 60 يوماً على انتهائها، ويجب في كل الأحوال تقديمه قبل تاريخ الانتهاء (المادة 24/2 من قانون 6458).", "جدّد التأمين الصحي ليغطي الفترة الجديدة كاملة.", "تأكد من أن عنوان النفوس محدّث ومطابق لعقد الإيجار الحالي.", "ادفع رسوم التجديد (Harç + Kart Bedeli) واحتفظ بالإيصال.", "اذهب في الموعد المحدد مع الملف الكامل لإتمام البيومتري.", "خلال فترة الانتظار تبقى إقامتك القديمة سارية المفعول قانونياً حتى صدور القرار."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'tourist-extension';

UPDATE consultant_scenarios SET
    cost = 'GSS للأجانب: القسط محدد بالقانون = 12% من ضعف الحد الأدنى الإجمالي للأجور. لعام 2026: 12% × (2 × 33,030) = 7,927.20 ل.ت شهرياً (نحو 95,126 ل.ت سنوياً) — أساس الاشتراك (ضعف الحد الأدنى) في المادة 80، ونسبة الـ12% في المادة 81/و من قانون 5510. | التأمين الخاص: أرخص بكثير في معظم الحالات، ويُقبل لتجديد الإقامة.',
    tip = 'بالنسبة للأجانب المسجلين في GSS، لا توجد مهلة 60 يوماً: يُشترط ألا يكون عليك أي دين أقساط إطلاقاً في تاريخ مراجعتك للمشفى، إضافةً إلى 30 يوم قسط مدفوع خلال السنة السابقة (المادة 67/1-ج من قانون 5510). تأخير قسط واحد يكفي لحرمانك من التغطية. يمكنك الاستعلام عبر e-Devlet → SGK.',
    last_update = '2026-07'
WHERE id = 'tourist-health-insurance';

UPDATE consultant_scenarios SET
    cost = 'التأمين (Depozito): حد أقصى ثلاثة أشهر إيجار (المادة 342 من قانون الالتزامات 6098). | عمولة المكتب العقاري: بحكم النظام لا تتجاوز أجرة شهر واحد بدون ضريبة القيمة المضافة كإجمالي عن الكراء، وتُدفع مناصفةً بين الطرفين ما لم يُتفق في عقد الوساطة على خلاف ذلك — أي أن حصتك عادةً نصف شهر (المادة 20/2 والمادة 20/5 من لائحة تجارة العقارات بصيغتها المعدلة في 14/10/2020).',
    steps = '["اطلب عقداً مكتوباً بالتركية (Kira Sözleşmesi) وترجمه إن لزم", "تأكد من وجود: اسم المالك، العنوان، المبلغ، مدة العقد، شروط التجديد", "لا توقّع على تعهد إخلاء (Tahliye Taahhüdü) مع العقد — وقّعه لاحقاً فقط إذا أردت", "لا تسلّم التأمين (Depozito) نقداً ولا تحوّله إلى حساب المالك. القانون يوجب إيداع المبلغ في حساب توفير لأجل باسمك لا يستطيع المالك السحب منه دون موافقتك؛ وإذا لم يُبلّغ المالك البنك خطياً خلال ثلاثة أشهر من انتهاء العقد بأنه أقام دعوى أو تنفيذاً ضدك، وجب على البنك إعادة المبلغ إليك بناءً على طلبك (المادة 342 من قانون الالتزامات 6098).", "سجّل عنوانك في النفوس خلال 20 يوماً من الانتقال", "صوّر حالة الشقة عند الاستلام كدليل"]'::jsonb,
    last_update = '2026-07'
WHERE id = 'tourist-lease-contract';

UPDATE consultant_scenarios SET
    cost = 'بطاقة الإقامة (Kart Bedeli): 964 ل.ت • الشهر الأول (Harç): حد أقصى 3,359.90 ل.ت • كل شهر إضافي: 2,232.30 ل.ت • الإعفاء من رسم الطابع (Harç) مرتبط بالجنسية وفق مبدأ المعاملة بالمثل ويشمل: سوريا وفلسطين والتشيك والدنمارك وإيرلندا وكوسوفو ونيبال وسريلانكا وتركمانستان وقبرص الشمالية — هؤلاء يدفعون بدل البطاقة فقط. لا يوجد إعفاء للطلاب، ولا إعفاء لأي جنسية من بدل البطاقة (964 ل.ت). • التأمين الصحي: 4,000-10,000 ل.ت/سنة • للتفاصيل الكاملة: /article/residence-permit-fees-2026 • رسم فيزا الدخول الواحد (Tek Giriş Vize Harcı): 9,376.40 ل.ت لعام 2026 — إلزامي على من دخل تركيا بالإعفاء من الفيزا ويقدّم أول طلب إقامة من الداخل، وعلى من تجاوز مدة إقامته القانونية، ما لم يكن من جنسية معفاة من هذا الرسم • رسوم الطابع تختلف بحسب الجنسية وفق مبدأ المعاملة بالمثل؛ المبالغ المذكورة (348.10 ل.ت/يوم للشهر الأول بحد أقصى 3,359.90 ل.ت، و2,232.30 ل.ت لكل شهر تالٍ) هي التعرفة العامة. راجع جدول الرسوم حسب الدول على صفحة goc.gov.tr «Belge Bedeli ve Harç Miktarı» للتأكد من مبلغ جنسيتك',
    docs = '["جواز سفر ساري المفعول (صلاحية لا تقل عن 60 يوماً بعد مدة الإقامة المطلوبة)", "صور شخصية بيومترية (4 صور، خلفية بيضاء)", "تأمين صحي يغطي كامل فترة الإقامة (شركة تأمين معتمدة من إدارة الهجرة)", "عقد إيجار مصدق من النوتير أو سند ملكية (Tapu)", "إثبات القدرة المالية: المعيار النظامي هو القدرة على تغطية مصروف شهري لا يقل عن صافي الحد الأدنى للأجور المعمول به في سنة التقديم (28,075.50 ل.ت شهرياً لعام 2026)، مع ثلث الحد الأدنى إضافةً عن كل فرد من أفراد الأسرة، ولا يُقبل الاستناد إلى تعهّد طرف ثالث وحده (المادة 22/6 من اللائحة التنفيذية).", "وصل دفع رسوم الإقامة (Harç + Kart Bedeli)"]'::jsonb,
    legal = 'قاعدة 90/180: المواطنون المعفون من الفيزا يمكنهم البقاء 90 يوماً كحد أقصى خلال كل 180 يوم. التقديم بعد انتهاء هذه المدة يُعتبر مخالفة (overstay) ويعرضك لغرامة ومنع دخول. المادة 11/1 من قانون الأجانب والحماية الدولية رقم 6458 (قاعدة 90 يوماً في كل 180 يوماً)، والمادة 102 منه (الغرامات الإدارية).',
    steps = '["تأكد من دخولك تركيا بشكل قانوني وأن فيزتك أو فترة الإعفاء (90 يوماً من كل 180 يوم) لا تزال سارية.", "بيّن عنوان سكنك داخل طلب الإقامة الإلكتروني. أما تسجيل العنوان في النفوس فيصبح إلزامياً خلال 20 يوم عمل من تسلّمك بطاقة الإقامة (أو من تاريخ دخولك إن كنت قد حصلت على الإقامة من قنصلية تركية بالخارج) — المادة 22/12 من اللائحة التنفيذية والمادة 50/3 من قانون 5490.", "قدّم طلب الإقامة إلكترونياً عبر بوابة e-ikamet (e-ikamet.goc.gov.tr) واحصل على موعد.", "ادفع رسوم الإقامة عبر الإنترنت أو في بنك مُعتمد: رسم الكرت (Kart Bedeli) + رسم الطابع (Harç Bedeli).", "جهّز ملف المستندات الكامل واذهب في الموعد المحدد إلى إدارة الهجرة (İl Göç İdaresi) لتقديم البيانات البيومترية.", "انتظر قرار الموافقة (عادة 30-90 يوم). خلال فترة الانتظار يحق لك البقاء في تركيا حتى لو انتهت الفيزا."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'tourist-new';

UPDATE consultant_scenarios SET
    cost = 'لا توجد «غرامة يومية» بمعنى العقوبة، بل يُحصَّل رسم الإقامة عن مدة التجاوز مضاعفاً: تعرفة 2026 هي 348.10 ل.ت عن كل يوم في الشهر الأول (بحد أدنى 653.70 ل.ت وبحد أقصى 3,359.90 ل.ت للشهر الأول)، و2,232.30 ل.ت عن كل شهر تالٍ، ثم يُحصَّل المبلغ بضعفه. مثال: تجاوز 30 يوماً ≈ 6,719.80 ل.ت. أصحاب الجنسيات المعفاة من رسم الإقامة (ومنها سوريا وفلسطين) لا يُطالَبون بهذا الرسم. بالإضافة لتكلفة تذكرة السفر.',
    legal = 'لا يوجد جدول قانوني يربط مدة التجاوز بمدة المنع. القاعدة النظامية (المادة 8/2 من اللائحة التنفيذية): من تجاوز أكثر من 10 أيام وراجع الولاية للخروج قبل صدور/تبليغ قرار ترحيل بحقه، لا يتجاوز منع الدخول سنة واحدة بشرط دفع الرسوم والغرامات؛ ومن توجّه بنفسه إلى بوابة حدودية للخروج ودفع ما عليه، قد لا يُصدر بحقه منع دخول أصلاً. والحد الأقصى العام لمنع الدخول 5 سنوات (المادة 9/3 من قانون 6458). قاعدة 90/180 يجب مراعاتها: حتى لو لم تتجاوز 90 يوماً إجمالياً، فإن حسابها يتم ضمن كل فترة 180 يوم متحركة (rolling period). المادة 9 من قانون 6458 والمادة 8 من لائحته التنفيذية (منع الدخول)، والمادة 11/1 من القانون (قاعدة 90/180)، والمادة 56 (مهلة مغادرة تركيا).',
    steps = '["حدد مدة التجاوز: احسب عدد الأيام من تاريخ انتهاء الفيزا/الإقامة حتى اليوم.", "راجع إدارة الهجرة (İl Göç İdaresi) طوعياً — المراجعة الطوعية تخفف العقوبة مقارنة بالضبط في نقطة تفتيش.", "ادفع الغرامة المقررة: تُحسب يومياً وتتراكم (حوالي 100-150 ليرة/يوم حسب تحديث 2026).", "قد يصدر بحقك قرار منع دخول — ولكن القانون يجيز عدم إصداره إذا بادرتَ بنفسك قبل أن تُضبط ودفعتَ الرسوم والغرامات المستحقة، أو إذا غادرت خلال مهلة «الدعوة للمغادرة» (المادة 9/4 و9/5 من قانون 6458).", "غادر تركيا خلال المهلة المحددة (عادة 7-30 يوماً بعد التبليغ).", "إن صدر بحقك قرار ترحيل (Sınır Dışı Etme Kararı) فمهلة الطعن أمام المحكمة الإدارية 7 أيام فقط من تاريخ التبليغ، ولا يجوز ترحيلك خلال مهلة رفع الدعوى ولا حتى انتهاء المحاكمة (المادة 53/3 من قانون 6458). أما قرار منع الدخول وحده فمهلة الطعن فيه 60 يوماً (المادة 7 من قانون 2577)."]'::jsonb,
    tip = 'إذا اكتشفت تجاوزك، راجع الهجرة فوراً ولا تنتظر. المراجعة الطوعية تمنحك معاملة أفضل. إن لم يكن صدر بحقك قرار ترحيل، فإن التوجّه بنفسك إلى بوابة حدودية للخروج ودفع الرسوم والغرامات المستحقة هو الطريق الذي قد لا يُفرض معه منع دخول إطلاقاً (المادة 8/2-ج من اللائحة التنفيذية)، بينما المراجعة الطوعية للولاية تحصر المنع بسنة كحد أقصى (المادة 8/2-ب). المهم ألا تُضبط في تفتيش قبل أن تبادر بنفسك، وأن تدفع كامل ما عليك عند الخروج.',
    last_update = '2026-07'
WHERE id = 'tourist-overstay';

UPDATE consultant_scenarios SET
    legal = 'رفض طلب الإقامة يُبلَّغ وفق المادة 25 من قانون 6458، ومهلة الطعن القضائي أمام المحكمة الإدارية 60 يوماً من تاريخ التبليغ (المادة 7 من قانون القضاء الإداري 2577). تنبيه منفصل: إن كان ما تسلّمته قرار ترحيل (Sınır Dışı Etme Kararı) وليس قرار رفض، فمهلة الطعن 7 أيام فقط (المادة 53/3 من قانون 6458). أضف: «القانون يُلزم الإدارة عند الرفض أو الإلغاء أو عدم التمديد بأن تراعي روابطك العائلية في تركيا، ومدة إقامتك فيها، ووضعك في بلدك الأصلي، والمصلحة الفضلى للطفل — ويجيز لها تأجيل القرار لهذه الأسباب (المادة 25/1 من قانون 6458). اجعل هذه النقاط محور اعتراضك أو دعواك، وأرفق ما يثبتها». قرار الرفض لا يعني منع دخول — يمكنك المغادرة والعودة والتقديم مجدداً إلا إذا صدر بحقك كود منع.',
    steps = '["اقرأ التبليغ بدقة: سيتضمن سبب الرفض. وعند رفض الطلب أو عدم تمديد الإقامة تُسلَّم لك وثيقة معفاة من الرسوم تتيح البقاء في تركيا لمدة تصل إلى 10 أيام فقط (المادة 22/11 من اللائحة التنفيذية) — تصرّف داخل هذه المهلة ولا تعتمد على مدة أطول.", "الطعن الإداري (İtiraz): يمكن تقديم اعتراض خطي لإدارة الهجرة في أي وقت داخل مهلة الـ60 يوماً المخصصة لرفع الدعوى، وتقديمه يوقف سريان هذه المهلة. إن لم تردّ الإدارة خلال 30 يوماً يُعدّ الاعتراض مرفوضاً وتستأنف المهلة السير مع احتساب الأيام التي مضت قبل الاعتراض (المادة 11 من قانون 2577). الاعتراض مجاني ولا يحتاج محامياً.", "الطعن القضائي (İdare Mahkemesi): إذا رُفض الاعتراض الإداري، قدّم دعوى أمام المحكمة الإدارية خلال 60 يوماً من تاريخ التبليغ الأصلي.", "رفع الدعوى وحده لا يوقف تنفيذ قرار الرفض (المادة 27/1 من قانون 2577). يمكنك أن تطلب من المحكمة «وقف التنفيذ»، لكنها لا تقرره إلا إذا اجتمع شرطان معاً: احتمال ضرر يصعب أو يستحيل تداركه، ومخالفة القرار الواضحة للقانون — وغالباً بعد تلقّي دفاع الإدارة (المادة 27/2). وحتى صدور قرار وقف التنفيذ، وثيقتك تتيح البقاء 10 أيام فقط؛ استشر محامياً فوراً.", "إذا كان الرفض بسبب نقص مستندات (مثل التأمين أو كشف الحساب)، يمكنك تقديم طلب جديد فوراً بعد استكمال النواقص."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'tourist-reject';

UPDATE consultant_scenarios SET
    tip = 'الحدود الرسمية معلنة ولا تحتاج تخميناً: يجب التصريح لموظف الجمارك عند الدخول أو الخروج إذا كان معك أكثر من 25,000 ليرة تركية، أو ما يعادل 10,000 يورو بالعملات الأجنبية. التصريح يتم على «نموذج التصريح النقدي» (Nakit Beyan Formu) الذي تطلبه من موظف الجمارك. وإذا لم تصرّح واكتُشف المبلغ: غرامة إدارية بنسبة 10% من المبلغ غير المصرَّح عنه، ويُوضع كامل النقد الذي بحوزتك تحت الحجز. تحقق من الأرقام قبل السفر على موقع وزارة التجارة (ticaret.gov.tr).',
    last_update = '2026-07'
WHERE id = 'travel-cash-limit';

UPDATE consultant_scenarios SET
    description = 'رسم مغادرة البلاد (Yurt dışına çıkış harcı) لا يُفرض على الأجانب: القانون 5597 يفرضه على مواطني الجمهورية التركية عند الخروج فقط. المبلغ القانوني أُعيد تحديده بـ 1,000 ليرة بقرار رئاسي رقم 10381 (الجريدة الرسمية 9/9/2025) ويُرفع سنوياً بنسبة إعادة التقييم؛ راجع الرقم المطبَّق حالياً على موقع GİB. يُدفع إلكترونياً عبر «الدائرة الضريبية الرقمية» أو من نقاط البيع في المطار.',
    steps = '["قبل الذهاب للمطار: رسم مغادرة البلاد مفروض على مواطني الجمهورية التركية فقط (المادة 1 من القانون 5597). إذا كنت أجنبياً — سواء بإقامة أو حماية مؤقتة أو كسائح — فأنت غير مشمول ولا يُطلب منك دفعه. أما إن كنت قد حصلت على الجنسية التركية فأنت مشمول، مع إعفاءات تشمل من لديه إقامة في الخارج ومن لم يُكمل 7 سنوات.", "تحقق من السعر الحالي وطريقة الدفع المعتمدة (مطار/إلكتروني/بنك).", "ادفع قبل الوصول لشباك الجوازات لتجنب التأخير.", "احتفظ بالإيصال حتى تتم إجراءات الخروج.", "إذا سافرت كثيراً: راقب التغييرات السنوية لأن السعر يتبدل."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'travel-exit-tax';

UPDATE consultant_scenarios SET
    description = 'الحد الرسمي معلن: يستطيع المسافر أن يُدخل إلى تركيا وأن يُخرج منها مصاغاً ذهبياً/مجوهرات من المعادن الثمينة تخصّه شخصياً ولا تحمل صفة تجارية، شرط ألا تتجاوز قيمتها 15,000 دولار أمريكي. ما زاد عن هذا الحد أو بدا تجارياً يخضع للتصريح الجمركي وقد تُطبَّق عليه رسوم أو يُحجز إن لم يُصرَّح عنه. احتفظ بالفواتير لإثبات القيمة، وراجع الأرقام على موقع وزارة التجارة (ticaret.gov.tr) قبل السفر.',
    last_update = '2026-07'
WHERE id = 'travel-gold';

UPDATE consultant_scenarios SET
    steps = '["تواصل مع شركة الطيران أولاً لأن لديهم شروط وزن/صندوق/حجز للحيوانات. وانتبه لقيد رسمي أهم: لا يُسمح بإدخال أكثر من حيوانين (2) بصحبة المسافر الواحد (مثلاً قطتان، أو قطة وكلب)، ويجب أن تكون كل الأوراق مُصدَرة بشكل منفصل لكل حيوان. كما أن دخول القطط والكلاب والنمس إلى تركيا لا يتم إلا عبر البوابات الحدودية التي تحددها وزارة الزراعة والغابات — تأكد من أن مطار وصولك من ضمنها.", "جهّز الشريحة الإلكترونية (Microchip) إن كانت مطلوبة.", "أكمل لقاح داء الكلب ضمن المدد المطلوبة، واستخرج شهادة صحية بيطرية رسمية.", "للدخول إلى تركيا، اختبار عيار الأجسام المضادة للكَلَب ليس اختيارياً: يجب سحب عينة الدم بعد آخر لقاح كَلَب بـ 30 يوماً على الأقل، ولا يُسمح بدخول الحيوان إلى تركيا قبل مرور 3 أشهر على تاريخ سحب العينة. مثال رسمي: لقاح 01/04 ← أبكر سحب دم 01/05 ← أبكر تاريخ دخول 01/08. يُعفى من شرط الثلاثة أشهر الحيوانُ تركي المنشأ العائد ومعه تقرير عيار سابق صالح. تحقق أيضاً من شروط بلد وجهتك إن كنت مسافراً من تركيا.", "في يوم السفر: احضر مبكراً، واحتفظ بكل الأوراق أصل + نسخ."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'travel-pets';

UPDATE consultant_scenarios SET
    steps = '["أسس شركة LTD بشكل نظامي وحدد نشاطاً حقيقياً قابلاً للإثبات (مبيعات/فواتير/موقع/مقر).", "معايير وزارة العمل المعلنة: يجب أن تكون حصتك في الشركة 20% على الأقل وبقيمة لا تقل عن 500,000 ليرة، وأن يكون رأس مال الشركة المدفوع 500,000 ليرة على الأقل (أو مبيعات صافية 8,000,000 ليرة أو صادرات 150,000 دولار). الشركة برأس مال الحد الأدنى (50,000 ليرة) لا تحقق الشرط.", "فعّل الالتزامات الشهرية: محاسب، ضرائب، دفاتر، وعنوان صحيح.", "رتب وضع التأمين: غالباً سيظهر التزام تأمين (Bağ-Kur) لصاحب الشركة/المدير حسب الحالة.", "شرط التوظيف محدد رسمياً: يجب توظيف خمسة مواطنين أتراك مقابل كل أجنبي. ويوجد أيضاً حد أدنى للأجر المصرَّح به حسب المنصب: 5 أضعاف الحد الأدنى للمدير التنفيذي، 4 أضعاف للمهندس/المعماري، 3 أضعاف للمدراء الآخرين، ضعفان للمهن التي تتطلب اختصاصاً.", "قدّم طلب إذن العمل عبر القنوات الرسمية بمساعدة المحاسب/مختص، وتابع حتى الموافقة."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'work-permit-company';

UPDATE consultant_scenarios SET
    cost = 'الرسوم الحكومية رقم ثابت منشور ولا يتغير حسب المدينة أو الشركة. تعرفة 2026: إذن عمل مؤقت لسنة 12,574.90 ليرة | لسنتين 25,149.80 | لثلاث سنوات 37,724.70 | غير محدد المدة أو مستقل 125,802.20 | إذن عمل الحماية المؤقتة لسنة 4,677.90 — يُضاف إلى كل منها 964.00 ليرة بدل الورقة الثمينة. المتغيّر فعلاً هو SGK الشهري ومصاريف المحاسب.',
    last_update = '2026-07'
WHERE id = 'work-permit-cost';

UPDATE consultant_scenarios SET
    cost = 'يتحملها صاحب العمل. رسوم 2026: 4,677.90 ليرة رسم إذن العمل لحاملي الحماية المؤقتة (سنة واحدة) + 964.00 ليرة بدل الورقة الثمينة (değerli kâğıt) = 5,641.90 ليرة. تنبيه: إذا لم تُدفع الرسوم خلال 30 يوماً من تاريخ الإشعار يُرفض الطلب.',
    description = 'يحتاج الكملك للإذن للعمل القانوني. صاحب العمل (الشركة) هو من يقدم لك. شرط أساسي: لا يمكن تقديم الطلب إلا بعد مرور ستة أشهر على تاريخ تسجيلك في الحماية المؤقتة (المادة 5 من لائحة أذون عمل الحماية المؤقتة) — قبل ذلك يرفض النظام الطلب تلقائياً.',
    steps = '["صاحب العمل يستخدم المحاسب المالي (Mali Müşavir) لتقديم الطلب عبر بوابة وزارة العمل. تحقق أولاً من الحصة (kota): كقاعدة عامة لا يتجاوز عدد العاملين تحت الحماية المؤقتة في المنشأة 10% من عدد الموظفين الأتراك، وفي المنشآت التي يقل مجموع عامليها عن عشرة يُسمح بعامل واحد فقط (المادة 8 من لائحة أذون عمل الحماية المؤقتة). استثناء مهم: إذا حصل صاحب العمل على وثيقة من مديرية العمل (İŞKUR) تثبت عدم العثور خلال الأسابيع الأربعة السابقة للطلب على مواطن تركي بنفس مؤهلات الوظيفة، جاز عدم تطبيق الحصة (المادة 8/3).", "الموافقة على الطلب عبر E-Devlet الخاص بك.", "دفع رسوم الإذن + بدل الورقة الثمينة من قِبل الشركة خلال 30 يوماً من تاريخ الإشعار وإلا يُرفض الطلب. وبعد الموافقة، على صاحب العمل تقديم إشعار بدء التأمين (sigortalı işe giriş bildirgesi) خلال 30 يوماً من تاريخ الموافقة أو التبليغ. تابع الأمرين بنفسك.", "انتظار بطاقة إذن العمل."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'work-permit-employee';

UPDATE consultant_scenarios SET
    steps = '["صاحب العمل يسجلك في SGK خلال 30 يوماً من بدء إذن العمل.", "إذا كنت تحت الحماية المؤقتة ولا تعمل: اختبار الدخل (Gelir Testi) الخاص بـ GSS مخصص للمواطنين الأتراك ولا ينطبق عليك. الآلية التي تخصك: تدفع \"رسم المشاركة\" (katılım payı) عند تلقي الخدمة الصحية، ثم إذا ثُبتت عدم قدرتك المادية بتنسيق بين وزارة الأسرة ورئاسة الهجرة، تستردّ ما دفعته من وقف التكافل (SYDV) بناءً على طلبك (المادة 27 من لائحة الحماية المؤقتة، المعدّلة في 28/11/2025).", "إذا ثبتت عدم القدرة المادية، قد تُعفى من الرسوم؛ وإلا يجب دفع قسط GSS شهرياً.", "تابع ديون GSS عبر e-Devlet لتجنب تراكم المبالغ."]'::jsonb,
    tip = 'نظام "الشرائح" في GSS أُلغي منذ 1/1/2018 (القانون 6824)؛ لم يعد هناك تصنيف بأعلى شريحة. القسط موحّد: 1,981.80 ليرة شهرياً في 2026. وحاملو الحماية المؤقتة ليسوا مشمولين بنظام GSS أصلاً فلا تتراكم عليهم ديون GSS.',
    last_update = '2026-07'
WHERE id = 'work-sgk';

UPDATE consultant_scenarios SET
    description = 'Bağ-Kur هو نظام تأمين/تقاعد لأصحاب الأعمال. غالباً يكون هناك التزام دفع شهري حتى لو كان الدخل ضعيفاً. تجاهله لا يعني فقط تراكم الديون: إذا تجاوز دَينك 60 يوماً من الأقساط تُحرم أنت ومن تعيلهم من الاستفادة من الخدمات الصحية بالكامل (المادة 67 من قانون الضمان 5510)، إلا إذا كان الدَين مُقسّطاً رسمياً وتلتزم بأقساطه.',
    last_update = '2026-07'
WHERE id = 'worker-bagkur';

UPDATE consultant_scenarios SET
    cost = 'SGK (Bağ-Kur 4/b) شهري 2026: الحد الأدنى ≈ 11,808 ليرة (35.75% من الحد الأدنى للأجر البالغ 33,030 ليرة) | ضريبة الدخل: 15-40%',
    last_update = '2026-07'
WHERE id = 'worker-freelance-rules';

UPDATE consultant_scenarios SET
    steps = '["وثّق كل شيء: عقد العمل، كشوف الرواتب، رسائل التواصل", "أرسل إنذاراً رسمياً عبر النوتر (İhtarname)", "قدّم طلب وساطة إلزامية (Arabuluculuk) — مجاني للعمال", "انتبه للمواعيد: في حالة الفصل غير القانوني يجب تقديم طلب الوساطة خلال شهر واحد من تاريخ تبليغك بإنهاء العقد (المادة 20 من قانون العمل 4857)، ثم رفع الدعوى في محكمة العمل خلال أسبوعين من تاريخ محضر الوساطة الأخير. تجاوز أي من الموعدين يُسقط حقك في العودة إلى العمل.", "يمكنك المطالبة بالراتب المتأخر + تعويض الإنهاء غير العادل (Kıdem + İhbar Tazminatı)"]'::jsonb,
    tip = 'إذا لم يُدفع راتبك في موعده يحق لك فسخ العقد فوراً وبدون إشعار مسبق لسبب مُحق (المادة 24/II-e من قانون العمل 4857) — وهذا الحق لا يشترط انتظار 20 يوماً. أما مهلة الـ20 يوماً (المادة 34) فتمنحك حقاً مختلفاً: الامتناع عن أداء العمل دون أن يُعتبر ذلك إضراباً. وعند الفسخ من طرفك: تستحق تعويض الأقدمية (Kıdem) بشرط إتمام سنة كاملة على الأقل، ولا تستحق تعويض الإشعار (İhbar).',
    last_update = '2026-07'
WHERE id = 'worker-rights-violation';

UPDATE consultant_scenarios SET
    legal = 'لوائح النقل والبلديات والمرور (تختلف حسب المدينة) + قانون العمل الدولي رقم 6735. الأهم بالنسبة للأجنبي: نقل الركاب مقابل المال بلا إذن عمل يُعدّ عملاً حراً بدون إذن، وتُفرض عليك غرامة إدارية بموجب المادة 23/5-ب-2، والأخطر أن المادة 23/8 توجب إبلاغ وزارة الداخلية بك تمهيداً للترحيل.',
    last_update = '2026-07'
WHERE id = 'worker-uber-illegal';

-- ═══════════════════════════════════════════════════════════════════════
-- التحقّق: يجب أن يرجع صفر صفوف
SELECT id FROM consultant_scenarios WHERE (id || ' ' || coalesce(cost,'') || ' ' || coalesce(legal,'') || ' ' || coalesce(tip,'') || ' ' || coalesce(description,'') || ' ' || steps::text) LIKE '%لمدة 5 سنوات%'
   OR (id || ' ' || coalesce(cost,'') || ' ' || coalesce(legal,'') || ' ' || coalesce(tip,'') || ' ' || coalesce(description,'') || ' ' || steps::text) LIKE '%لطلب إذن الزيارة المؤقتة لسوريا%'
   OR (id || ' ' || coalesce(cost,'') || ' ' || coalesce(legal,'') || ' ' || coalesce(tip,'') || ' ' || coalesce(description,'') || ' ' || steps::text) LIKE '%75%% من الحد الأدنى%'
   OR (id || ' ' || coalesce(cost,'') || ' ' || coalesce(legal,'') || ' ' || coalesce(tip,'') || ' ' || coalesce(description,'') || ' ' || steps::text) LIKE '%كانت ~65%%%'
   OR (id || ' ' || coalesce(cost,'') || ' ' || coalesce(legal,'') || ' ' || coalesce(tip,'') || ' ' || coalesce(description,'') || ' ' || steps::text) LIKE '%التأمين الصحي المجاني للحماية المؤقتة توقف%';

-- عدد الصفوف المحدّثة اليوم — المتوقع 98
SELECT count(*) FROM consultant_scenarios WHERE last_update = '2026-07';
